const icon = (n, extra = '') => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${extra}>${IC[n] || ''}</svg>`;

/* ============ Navigation ============ */
const NAV = [
  ['Overview', [['dashboard', 'Dashboard', 'dash'], ['chat', 'AI Career Chat', 'chat']]],
  ['Profile', [['profile', 'Career Profile', 'user'], ['resumes', 'Resumes', 'file'], ['preferences', 'Job Preferences', 'sliders']]],
  ['Jobs', [['discover', 'Job Discovery', 'search'], ['jobs', 'Recommended Jobs', 'star']]],
  ['Applications', [['approvals', 'Approval Center', 'check'], ['tracker', 'Application Tracker', 'board']]],
  ['Insights', [['shortlisting', 'Shortlisting Analysis', 'up'], ['rejections', 'Rejection Analysis', 'down'], ['interviews', 'Interview Prep', 'mic'], ['offers', 'Offers', 'gift'], ['analytics', 'Career Analytics', 'chart']]],
  ['System', [['alerts', 'Notifications', 'bell'], ['activity', 'Activity Log', 'list'], ['config', 'Configuration', 'gear']]],
];
const TITLES = Object.fromEntries(NAV.flatMap(g => g[1].map(([k, t]) => [k, t])));
function route() { const h = (location.hash || '').replace(/^#/, ''); const m = h.match(/^(job)-([a-z0-9]+)$/i); if (m) return { view: 'job', id: m[2] }; return { view: TITLES[h] ? h : 'dashboard', id: null }; }
function go(hash) { if (location.hash === '#' + hash) render(); else location.hash = hash; }

function counts() {
  const J = Object.values(S.jobs);
  return { approvals: J.filter(j => j.stage === 'AwaitingApproval' || j.stage === 'Approved').length, interviews: J.filter(j => j.stage === 'InterviewScheduled').length, unread: bellItems().filter(n => !n.read).length };
}
function layout(view, title, body) {
  const c = counts();
  const navHtml = NAV.map(([g, items]) => `<h4>${g}</h4>` + items.map(([k, t, ic]) => `<a href="#${k}" class="${view === k || (view === 'job' && k === 'jobs') ? 'on' : ''}" ${view === k ? 'aria-current="page"' : ''}>${icon(ic)}<span>${t}</span>${k === 'approvals' && c.approvals ? `<span class="cnt">${c.approvals}</span>` : ''}${k === 'interviews' && c.interviews ? `<span class="cnt">${c.interviews}</span>` : ''}</a>`).join('')).join('');
  const modeNote = { cloud: 'Saved to your cloud database', local: 'Saved in this browser only', memory: 'Not saved: storage unavailable' }[S.mode] || 'Loading…';
  const aiNote = AI.available() && S.settings.cloudPublic ? AI.name + ' + local engine' : 'Local engine';
  return `<button class="skip" type="button" data-act="skip">Skip to content</button><div class="shell"><aside class="rail" id="rail"><div class="brand"><div class="brand-mark">AC</div><div><b>AI Career Agent</b><small>Job search, under your control</small></div></div><nav class="nav" aria-label="Main">${navHtml}</nav>
  <div class="rail-foot">${S.mode === 'cloud' ? `<span>Signed in as <b>${esc((S.session && S.session.user.email) || '')}</b></span>` : `<span>${CLOUD ? 'Not signed in' : 'Single-browser mode'}</span>`}<span class="tiny">${esc(modeNote)}</span><span class="tiny">AI: ${esc(aiNote)}</span>${S.mode === 'cloud' ? '<button class="btn sm" type="button" data-act="signout">Sign out</button>' : CLOUD ? '<button class="btn sm primary" type="button" data-act="goto-auth">Sign in</button>' : ''}</div></aside>
  <div class="rail-shade" data-act="menu" aria-hidden="true"></div>
  <main class="main" id="main"><header class="top" id="top"><button class="icon-btn menu-btn" type="button" data-act="menu" aria-label="Open menu">${icon('menu')}</button><h1>${esc(title)}</h1><span class="sp"></span>
  ${themeSeg()}<button class="icon-btn" type="button" data-act="notifs" aria-label="Notifications${c.unread ? `, ${c.unread} unread` : ''}" aria-expanded="${S.ui.notifOpen ? 'true' : 'false'}">${icon('bell')}${c.unread ? `<span class="dot">${c.unread}</span>` : ''}</button>${S.ui.notifOpen ? notifPanel() : ''}<div class="scroll-prog" aria-hidden="true"><i id="scroll-prog"></i></div></header>
  <div class="content" id="content" tabindex="-1">${banners()}${body}</div><button class="to-top" type="button" data-act="to-top" id="to-top" aria-label="Back to top" hidden>${icon('arrowUp')}</button></main></div>`;
}
const THEMES = [['light', 'Light', 'sun'], ['dark', 'Dark', 'moon'], ['auto', 'Auto', 'auto']];
function themeSeg() { const cur = Theme.get(); return `<div class="seg" role="group" aria-label="Theme">${THEMES.map(([k, l, ic]) => `<button type="button" data-act="theme" data-theme="${k}" aria-pressed="${cur === k}" title="${k === 'auto' ? 'Auto: follow your device setting' : l + ' theme'}" aria-label="${l} theme">${icon(ic)}</button>`).join('')}</div>`; }
function banners() {
  const out = [];
  if (S.mode === 'local') out.push(`<div class="banner info"><span>The cloud database isn’t connected yet, so data is saved in this browser only. Add your Supabase keys to <code>config.js</code> (see the README).</span></div>`);
  const st = S.server && S.server.status;
  if (S.mode === 'cloud' && st && st.lastRunAt && (Date.now() - new Date(st.lastRunAt)) > 3 * 3600e3) out.push(`<div class="banner bad"><span>The alert server last ran ${esc(fmtDT(st.lastRunAt))}. Alerts and job discovery are paused. Open GitHub → Actions and re-enable the “Career agent” workflow.</span><span class="sp"></span><a class="btn sm" href="#alerts">Details</a></div>`);
  if (S.mode === 'memory') out.push(`<div class="banner bad"><span>Storage is unavailable in this view, so changes last only until you close the page.</span></div>`);
  if (S.loadNote) out.push(`<div class="banner bad"><span>${esc(S.loadNote)}</span></div>`);
  return out.join('');
}
function bellItems() { return [...S.notifs.map(n => ({ ...n, src: 'app' })), ...Object.values(S.alerts || {}).map(a => ({ id: a.id, t: a.t, message: a.title + (a.body ? ' — ' + a.body : ''), jobId: a.jobId, read: !!a.read, src: 'server' }))].sort((a, b) => (b.t || '').localeCompare(a.t || '')); }
function notifPanel() {
  const items = bellItems().slice(0, 40);
  return `<div class="notif-panel" role="dialog" aria-label="Notifications"><div class="row between" style="padding:10px 14px;border-bottom:1px solid var(--line)"><b>Notifications</b><button class="btn sm ghost" type="button" data-act="notifs-read">Mark all read</button></div>
  ${items.length ? items.map(n => `<div class="notif ${n.read ? '' : 'unread'}"><span>${esc(n.message)}</span><span class="tiny muted">${fmtDT(n.t)}${n.src === 'server' ? ' · alert' : ''}${n.jobId && S.jobs[n.jobId] ? ` · <a href="#job-${n.jobId}">Open</a>` : ''}</span></div>`).join('') : '<div class="empty">No notifications yet.</div>'}<div style="padding:10px 14px"><a class="btn sm" href="#alerts">Notification settings</a></div></div>`;
}

/* ============ Shared fragments ============ */
const hostOf = u => { try { return new URL(/^https?:/i.test(u) ? u : 'https://' + u).hostname; } catch (e) { return String(u).slice(0, 40); } };
const scoreRing = (s, lg = false) => { const c = category(s || 0); const col = { good: 'var(--good)', acc: 'var(--accent)', warn: 'var(--warn)', bad: 'var(--bad)' }[c.tone]; return `<div class="score ${lg ? 'lg' : ''}" style="--v:${s || 0};--c:${col}" data-v="${s ?? '–'}" role="img" aria-label="Match score ${s}"></div>`; };
const engineTag = e => e === 'ai' ? `<span class="engine ai" title="Produced by ${AI.name}">${AI.name}</span>` : e === 'server' ? '<span class="engine" title="Found by the scheduled server job">Server</span>' : e === 'claude' ? '<span class="engine ai">Claude</span>' : '<span class="engine" title="Produced by the in-browser rules engine">Local engine</span>';
const chipList = (arr, cls = '') => (arr && arr.length) ? `<div class="chips">${arr.map(s => `<span class="chip ${cls}">${esc(s)}</span>`).join('')}</div>` : '<span class="muted small">None</span>';
const emptyState = (title, text, actions = '') => `<div class="empty"><b>${esc(title)}</b><span>${text}</span>${actions ? `<div class="row" style="justify-content:center">${actions}</div>` : ''}</div>`;
const postedAgo = j => { const d = daysAgo(j.postedAt || ''); return d == null || isNaN(d) ? '' : d <= 0 ? 'Posted today' : d === 1 ? 'Posted yesterday' : d < 60 ? `Posted ${d} days ago` : `Posted ${Math.round(d / 30)} months ago`; };
const closedPill = j => j.closed ? '<span class="pill bad">Closed</span>' : j.expired ? '<span class="pill bad">Deadline passed</span>' : '';
const jobMeta = j => `<div class="meta"><span>${esc(j.company)}</span><span>${esc(j.workMode === 'remote' ? (/india/i.test(j.location || '') ? 'Remote · India' : 'Remote') : j.location || 'Location not stated')}${j.workMode && j.workMode !== 'remote' ? ' · ' + j.workMode : ''}</span><span>${esc(salaryRange(j.salaryMin, j.salaryMax))}</span><span>${j.expMin != null ? esc(`${j.expMin}${j.expMax != null ? '–' + j.expMax : '+'} yrs`) : 'Exp. not stated'}</span><span>${esc(SOURCE_NAME[j.source] || j.source)}</span>${postedAgo(j) ? `<span>${postedAgo(j)}</span>` : ''}</div>`;
function jobCard(j) {
  const m = j.match || {}; const cat = category(m.score || 0);
  return `<div class="job-card ${cat.k}${isClosed(j) ? ' closed' : ''}" data-act="open-job" data-id="${j.id}" tabindex="0" role="link" aria-label="${esc(j.title)} at ${esc(j.company)}, match ${m.score ?? 'not scored'}">${scoreRing(m.score)}<div class="stack" style="gap:5px;min-width:0"><div class="row"><h3>${esc(j.title)}</h3>${j.fresh ? '<span class="pill hi">New</span>' : ''}${closedPill(j)}${j.suspicious ? '<span class="pill bad">Check listing</span>' : ''}</div>${jobMeta(j)}
  <div class="chips">${(m.matchedRequired || []).slice(0, 5).map(s => `<span class="chip match">${esc(s)}</span>`).join('')}${(m.missingRequired || []).slice(0, 4).map(s => `<span class="chip miss">${esc(s)}</span>`).join('')}</div></div>
  <div class="stack" style="align-items:flex-end;gap:6px">${stagePill(j.stage)}<span class="tiny muted">${esc(cat.label)}</span></div></div>`;
}
/* Search status: live progress while a search runs, otherwise what the last one found. */
function searchStatus() {
  const s = S.meta && S.meta.search; const run = S.ui.searching;
  if (run) return `<div class="search-run" role="status" aria-live="polite"><div class="row between small"><span id="search-label">${esc(searchLabel(run))}</span><span class="num muted" id="search-count">${run.total ? `${run.done}/${run.total}` : ''}</span></div><div class="bar prog"><i id="search-bar" style="transform:scaleX(${run.total ? Math.max(0.02, run.done / run.total) : 0.02})"></i></div></div>`;
  if (!s) return '';
  const st = s.stats;
  return `<p class="small muted search-last">Last search ${esc(relTime(s.at))}: read ${Number(st.listed || 0).toLocaleString('en-IN')} open roles on ${st.boardsOk} company boards, kept <b>${st.added} new</b> match${st.added === 1 ? '' : 'es'}${st.closed ? ` and flagged <b>${st.closed}</b> closed` : ''}.</p>`;
}
function setupSteps() {
  const hasProfile = !!(S.profile && (S.profile.name || (S.profile.skills || []).length));
  const hasPrefs = !!(S.prefs && (S.prefs.titles || []).length);
  const searched = !!(S.meta && S.meta.search) || Object.keys(S.jobs).length > 0;
  const started = Object.values(S.jobs).some(j => !['Discovered', 'Analyzed', 'Archived'].includes(j.stage));
  return [
    { done: hasProfile, title: 'Add your resume', text: 'Upload a PDF or DOCX. The profile it builds is what every match score and tailored resume is based on.', cta: `<a class="btn sm ${hasProfile ? '' : 'primary'}" href="#resumes">${hasProfile ? 'Review' : icon('upload') + 'Upload resume'}</a>` },
    { done: hasPrefs, title: 'Say what job you want', text: 'Titles, cities, experience and salary, in plain language. The search looks for exactly these.', cta: `<a class="btn sm ${hasProfile && !hasPrefs ? 'primary' : ''}" href="#preferences">${hasPrefs ? 'Edit' : 'Set preferences'}</a>` },
    { done: searched, title: 'Search open roles', text: `Reads ${boardsFor(S.notify).length} company career boards and the remote job feeds, and keeps the roles that fit you.`, cta: `<button class="btn sm ${hasProfile && hasPrefs && !searched ? 'primary' : ''}" type="button" data-act="find-jobs" ${hasPrefs && !S.ui.searching ? '' : 'disabled'}>${icon('search')}${S.ui.searching ? 'Searching…' : 'Search now'}</button>` },
    { done: started, title: 'Prepare your first application', text: 'Open a match, generate the tailored resume and check the answers. Nothing is sent until you approve it.', cta: `<a class="btn sm ${searched && !started ? 'primary' : ''}" href="#jobs">See matches</a>` },
  ];
}
function hbars(items, { unit = '', max } = {}) {
  const mx = max || Math.max(1, ...items.map(i => i.value));
  return `<div class="funnel">${items.map(i => `<div class="frow"><span>${esc(i.label)}</span><div class="bar"><i style="width:${Math.max(i.value ? 2 : 0, i.value / mx * 100)}%;${i.color ? 'background:' + i.color : ''}"></i></div><span class="num r" style="text-align:right">${esc(i.text ?? (i.value + unit))}</span></div>`).join('')}</div>`;
}
function vbars(data, { h = 160, color = 'var(--accent)', fmt = v => v } = {}) {
  if (!data.length) return '<p class="muted small">No data yet.</p>';
  const W = 560, pad = 28, bw = Math.min(56, (W - pad * 2) / data.length - 10); const mx = Math.max(1, ...data.map(d => d.value));
  const nice = Math.ceil(mx / 4) * 4 || 4; const step = (W - pad * 2) / data.length;
  const grid = [0, 0.5, 1].map(f => { const y = h - 22 - f * (h - 40); return `<line class="grid-l" x1="${pad}" x2="${W - 6}" y1="${y}" y2="${y}"/><text x="${pad - 6}" y="${y + 4}" text-anchor="end">${fmt(Math.round(nice * f * 10) / 10)}</text>`; }).join('');
  const bars = data.map((d, i) => { const bh = d.value / nice * (h - 40); const x = pad + i * step + (step - bw) / 2; const y = h - 22 - bh; return `<rect x="${x}" y="${y}" width="${bw}" height="${Math.max(0, bh)}" rx="3" fill="${d.color || color}"><title>${esc(d.label)}: ${fmt(d.value)}</title></rect>${d.value ? `<text x="${x + bw / 2}" y="${y - 4}" text-anchor="middle" style="fill:var(--ink)">${fmt(d.value)}</text>` : ''}<text x="${x + bw / 2}" y="${h - 6}" text-anchor="middle">${esc(d.label)}</text>`; }).join('');
  return `<svg class="chart" viewBox="0 0 ${W} ${h}" width="100%" role="img">${grid}${bars}</svg>`;
}

/* ============ Views ============ */
const V = {};
V.dashboard = () => {
  const A = analytics(); const J = Object.values(S.jobs);
  const tiles = [['Jobs found', 'Total jobs found', A.total, 'jobs'], ['Match 70+', 'Jobs matching my profile, 70 and above', A.matching, 'jobs'], ['Applied', 'Applications submitted', A.applied, 'tracker'], ['Shortlisted', 'Shortlisted applications', A.shortlisted, 'shortlisting'], ['Rejected', 'Rejected applications', A.rejected, 'rejections'], ['Interviews', 'Interviews scheduled', A.interviews, 'interviews'], ['Offers', 'Offers received', A.offers, 'offers']];
  const steps = setupSteps(); const setupDone = steps.slice(0, 3).every(x => x.done);
  const awaiting = J.filter(j => j.stage === 'AwaitingApproval' || j.stage === 'Approved');
  const upcoming = J.flatMap(j => ((j.app && j.app.interviews) || []).filter(iv => new Date(iv.at) > Date.now() - 3600e3).map(iv => ({ j, iv }))).sort((a, b) => a.iv.at.localeCompare(b.iv.at)).slice(0, 4);
  const top = J.filter(j => j.match && ['Analyzed', 'Shortlisted', 'ResumeGenerated'].includes(j.stage) && !isClosed(j)).sort((a, b) => b.match.score - a.match.score).slice(0, 4);
  const attention = [];
  awaiting.forEach(j => attention.push(`<li>${j.closed ? '<span class="pill bad">Closed</span>' : stagePill(j.stage)}<span><a href="#job-${j.id}">${esc(j.title)} · ${esc(j.company)}</a> — ${j.closed ? 'the employer has taken this role down' : j.stage === 'Approved' ? 'approved, ready to submit' : 'review and approve before anything is sent'}</span></li>`));
  J.filter(j => j.closed && ['Shortlisted', 'ResumeGenerated'].includes(j.stage)).forEach(j => attention.push(`<li><span class="pill bad">Closed</span><span><a href="#job-${j.id}">${esc(j.title)} · ${esc(j.company)}</a> — no longer listed; archive it or check the posting</span></li>`));
  upcoming.forEach(({ j, iv }) => attention.push(`<li><span class="pill good">Interview</span><span>${esc(fmtDT(iv.at))} · <a href="#job-${j.id}">${esc(j.company)}</a> (${esc(iv.type || 'Interview')}). <a href="#interviews">Prepare</a></span></li>`));
  const funnel = [['Discovered', A.total], ['Matched 70+', A.matching], ['Applied', A.applied], ['Shortlisted', A.shortlisted], ['Interviewed', A.interviews], ['Offers', A.offers]];
  const p = S.prefs || {}; const run = S.ui.searching;
  const setup = setupDone ? '' : `<section class="card setup"><div class="card-h"><h2>Get set up</h2><p>${steps.filter(x => x.done).length} of ${steps.length} done</p></div>
  <ol class="steps">${steps.map((x, i) => `<li class="step ${x.done ? 'done' : ''}${!x.done && steps.slice(0, i).every(y => y.done) ? ' next' : ''}"><span class="step-n" aria-hidden="true">${x.done ? icon('check') : i + 1}</span><div class="stack" style="gap:2px;flex:1;min-width:0"><b>${x.title}${x.done ? ' <span class="sr-only">(done)</span>' : ''}</b><span class="small muted">${x.text}</span></div>${x.cta}</li>`).join('')}</ol></section>`;
  const search = setupDone ? `<section class="card"><div class="card-h"><h2>Open roles</h2><span class="sp"></span><a class="btn sm ghost" href="#discover">Sources</a><button class="btn primary" type="button" data-act="find-jobs" ${run ? 'disabled' : ''}>${icon('search')}${run ? 'Searching…' : 'Search open roles'}</button></div>
  <div class="row small"><span class="muted">Looking for</span>${(p.titles || []).slice(0, 4).map(t => `<span class="chip acc">${esc(t)}</span>`).join('')}${(p.locations || []).length ? `<span class="muted">in</span>${p.locations.slice(0, 4).map(t => `<span class="chip">${esc(t)}</span>`).join('')}` : ''}<a href="#preferences">Change</a></div>${searchStatus()}</section>` : (run ? `<section class="card">${searchStatus()}</section>` : '');
  return `${setup}
  ${A.total ? `<div class="stats">${tiles.map(([l, full, v, h]) => `<a class="stat" href="#${h}" aria-label="${esc(full)}: ${v}"><b class="num" data-count="${v}">${v}</b><span>${esc(l)}</span></a>`).join('')}</div>` : ''}
  ${search}
  ${setupDone ? `<form novalidate class="card" data-form="quick-chat"><div class="row"><label for="qc" class="sr-only">Ask the agent</label><input type="text" id="qc" name="msg" placeholder="Tell the agent what to do, for example “Show only jobs with compatibility above 80%”" style="flex:1;min-width:200px"><button class="btn" type="submit">${icon('bolt')}Ask agent</button></div>
  <div class="suggest">${['Search now', 'Show only jobs with compatibility above 80%', 'Prepare applications for my top 3 jobs', 'Identify the most common missing technical skills'].map(x => `<button type="button" data-act="chat-suggest" data-msg="${esc(x)}">${esc(x)}</button>`).join('')}</div></form>` : ''}
  ${A.total || attention.length ? `<div class="grid g-side">
    <div class="stack" style="gap:16px">
      <div class="card"><div class="card-h"><h2>Needs your attention</h2><span class="sp"></span><a class="btn sm" href="#approvals">Approval Center</a></div>${attention.length ? `<ul class="list">${attention.join('')}</ul>` : '<p class="muted">Nothing is waiting on you.</p>'}</div>
      <div class="card"><div class="card-h"><h2>Top recommended jobs</h2><span class="sp"></span><a class="btn sm" href="#jobs">All jobs</a></div>${top.length ? `<div class="stack">${top.map(jobCard).join('')}</div>` : emptyState('No open matches right now', 'Run the search again, or widen the titles and cities in your preferences.', '<button class="btn primary" type="button" data-act="find-jobs">Search open roles</button>')}</div>
    </div>
    <div class="stack" style="gap:16px">
      <div class="card"><h2>Pipeline</h2>${hbars(funnel.map(([l, v]) => ({ label: l, value: v })))}<div class="row small muted"><span>Shortlist rate <b class="num">${A.shortlistRate}%</b></span><span>Interview rate <b class="num">${A.interviewRate}%</b></span><span>Offer conversion <b class="num">${A.offerRate}%</b></span></div></div>
      <div class="card"><div class="card-h"><h2>Recent agent activity</h2><span class="sp"></span><a class="btn sm" href="#activity">Log</a></div>${S.logs.length ? `<ul class="list small">${S.logs.slice(0, 6).map(l => `<li><span class="tiny muted num" style="min-width:84px">${fmtDT(l.t)}</span><span><b>${esc(l.agent)}</b> · ${esc(l.action)}</span></li>`).join('')}</ul>` : '<p class="muted small">No activity yet.</p>'}</div>
    </div>
  </div>` : ''}`;
};

V.chat = () => {
  const msgs = S.chat.length ? S.chat : [{ role: 'assistant', content: `I'm your career agent. Tell me what job you want in plain language, or give me a command. I prepare everything, but nothing is submitted without your approval.` }];
  const sugg = ['Search now', 'Show only jobs with compatibility above 80%', 'Customize my resume for my top job', 'Prepare applications for my top 10 jobs', 'Show me which applications are awaiting approval', 'Analyze why I am getting rejected', 'Identify the most common missing technical skills', 'Prepare me for my upcoming interview', 'Compare the salary and benefits of my offers'];
  return `<div class="card" style="gap:14px"><div class="card-h"><h2>Conversation</h2><span class="sp"></span>${AI.available() && S.settings.cloudPublic ? engineTag('ai') : engineTag('local')}<button class="btn sm ghost" type="button" data-act="chat-clear">Clear</button></div>
  <div class="chat" id="chat-log">${msgs.map(m => `<div class="msg ${m.role === 'user' ? 'u' : 'a'}">${m.role === 'user' ? esc(m.content) : `<div class="md">${mdHTML(m.content)}</div>`}</div>`).join('')}${S.ui.chatBusy ? `<div class="msg a" id="chat-live"><span class="busy"><span class="spin"></span>Thinking…</span> <button class="btn sm" type="button" data-act="chat-stop">Stop</button></div>` : ''}</div>
  <div class="suggest">${sugg.map(s => `<button type="button" data-act="chat-suggest" data-msg="${esc(s)}">${esc(s)}</button>`).join('')}</div>
  <form novalidate class="row" data-form="chat"><label for="chat-in" style="position:absolute;left:-9999px">Message</label><textarea id="chat-in" name="msg" rows="2" placeholder="Describe the job you want, or give a command such as “search now”" style="flex:1;min-height:52px"></textarea><button class="btn primary" type="submit" ${S.ui.chatBusy ? 'disabled' : ''}>Send</button></form></div>`;
};

V.profile = () => {
  const p = S.ui.draft || S.profile || normalizeProfile({});
  const filled = [p.name, p.email, p.phone, p.location, (p.skills || []).length, (p.education || []).length, (p.projects || []).length || (p.experiences || []).length, p.noticePeriod, p.expectedMin || (S.prefs && S.prefs.salaryMin)].filter(Boolean).length;
  const compl = Math.round(filled / 9 * 100);
  const inp = (n, l, v, t = 'text', ex = '') => `<label class="f"><span>${l}</span><input type="${t}" id="pf-${n}" name="${n}" value="${esc(v ?? '')}" ${ex}></label>`;
  const rows = (kind, arr, fields) => `<div class="stack" id="rep-${kind}">${(arr || []).map((it, i) => `<div class="repeat"><div class="fgrid">${fields.map(([f, l, t]) => t === 'area' ? `<label class="f wide"><span>${l}</span><textarea id="pf-${kind}-${i}-${f}" name="${kind}.${i}.${f}" rows="3">${esc(it[f] || '')}</textarea></label>` : `<label class="f"><span>${l}</span><input type="${t || 'text'}" id="pf-${kind}-${i}-${f}" name="${kind}.${i}.${f}" value="${esc(it[f] || '')}"></label>`).join('')}</div><div class="row"><span class="sp"></span><button class="btn sm danger" type="button" data-act="pf-del" data-kind="${kind}" data-i="${i}">Remove</button></div></div>`).join('')}<button class="btn sm" type="button" data-act="pf-add" data-kind="${kind}">+ Add ${kind === 'experiences' ? 'experience or internship' : kind.replace(/s$/, '')}</button></div>`;
  const wm = p.workModes || [];
  const et = p.employmentTypes || ['full_time'];
  return `<form novalidate class="stack" style="gap:16px" data-form="profile" id="profile-form">
  <div class="card"><div class="card-h"><h2>Career profile</h2><span class="pill ${compl >= 80 ? 'good' : 'warn'}">${compl}% complete</span><span class="sp"></span><a class="btn sm" href="#resumes">Upload or re-parse resume</a><button class="btn primary" type="submit">Save profile</button></div>
  <p class="muted small">Every tailored resume and application answer is built only from what is here. Your original resume file is kept unchanged on the Resumes page.</p></div>
  <div class="card"><h3>Contact</h3><div class="fgrid">${inp('name', 'Full name', p.name)}${inp('email', 'Email', p.email, 'email')}${inp('phone', 'Phone', p.phone, 'tel')}${inp('location', 'Current city', p.location)}${inp('linkedin', 'LinkedIn URL', p.linkedin, 'text', 'inputmode="url"')}${inp('github', 'GitHub URL', p.github, 'text', 'inputmode="url"')}${inp('portfolio', 'Portfolio URL', p.portfolio, 'text', 'inputmode="url"')}</div></div>
  <div class="card"><h3>Summary and level</h3><label class="f"><span>Professional summary</span><textarea id="pf-summary" name="summary" rows="3">${esc(p.summary)}</textarea></label>
  <div class="fgrid"><label class="f"><span>Experience level</span><select id="pf-level" name="experienceLevel">${['Fresher', 'Junior (1–3 yrs)', 'Mid-level (3–6 yrs)', 'Senior (6+ yrs)'].map(o => `<option ${p.experienceLevel === o ? 'selected' : ''}>${o}</option>`).join('')}</select></label>${inp('totalYears', 'Full-time experience (years)', p.totalYears, 'number', 'step="0.1" min="0"')}${inp('noticePeriod', 'Notice period', p.noticePeriod, 'text', 'placeholder="Immediate / 30 days"')}${inp('currentCtc', 'Current CTC (₹ per year, optional)', p.currentCtc, 'number', 'min="0" step="10000"')}${inp('expectedMinL', 'Expected salary from (LPA)', p.expectedMin != null ? lpaNum(p.expectedMin) : '', 'number', 'step="0.5" min="0"')}${inp('expectedMaxL', 'Expected salary to (LPA)', p.expectedMax != null ? lpaNum(p.expectedMax) : '', 'number', 'step="0.5" min="0"')}${inp('workAuth', 'Authorised to work in India?', p.workAuth, 'text', 'placeholder="Yes"')}</div></div>
  <div class="card"><h3>Job targets</h3><div class="fgrid">${inp('preferredRoles', 'Preferred roles (comma separated)', (p.preferredRoles || []).join(', '))}${inp('preferredLocations', 'Preferred locations', p.preferredLocations || '')}
  <div class="f"><span class="muted" style="font-size:12.5px">Work modes</span><div class="row">${['remote', 'hybrid', 'onsite'].map(m => `<label class="check"><input type="checkbox" name="workModes" value="${m}" ${wm.includes(m) ? 'checked' : ''}>${m[0].toUpperCase() + m.slice(1)}</label>`).join('')}</div></div>
  <div class="f"><span class="muted" style="font-size:12.5px">Employment types</span><div class="row">${Object.entries(EMP_LABEL).map(([k, l]) => `<label class="check"><input type="checkbox" name="employmentTypes" value="${k}" ${et.includes(k) ? 'checked' : ''}>${l}</label>`).join('')}</div></div>
  <label class="check"><input type="checkbox" name="relocate" value="1" ${p.relocate ? 'checked' : ''}>Open to relocating</label></div></div>
  <div class="card"><h3>Skills</h3><label class="f"><span>Technical skills, languages, frameworks, tools (comma separated)</span><textarea id="pf-skills" name="skills" rows="3">${esc((p.skills || []).join(', '))}</textarea></label>${(p.skills || []).length ? `<div class="chips">${p.skills.map(s => `<span class="chip">${esc(s)} <span class="tiny muted">${esc(skillCat(s))}</span></span>`).join('')}</div>` : ''}</div>
  <div class="card"><h3>Projects</h3>${rows('projects', p.projects, [['name', 'Project name'], ['technologies', 'Technologies'], ['link', 'Link'], ['description', 'What you built and how', 'area']])}</div>
  <div class="card"><h3>Experience and internships</h3>${rows('experiences', p.experiences, [['role', 'Role'], ['employer', 'Employer'], ['start', 'Start (YYYY-MM)'], ['end', 'End (YYYY-MM, blank = current)'], ['description', 'Responsibilities and results', 'area']])}</div>
  <div class="card"><h3>Education</h3>${rows('education', p.education, [['degree', 'Degree'], ['institution', 'Institution'], ['year', 'Year'], ['score', 'CGPA / %']])}</div>
  <div class="card"><div class="grid g2"><label class="f"><span>Certifications (one per line)</span><textarea id="pf-certs" name="certifications" rows="4">${esc((p.certifications || []).join('\n'))}</textarea></label><label class="f"><span>Achievements (one per line)</span><textarea id="pf-ach" name="achievements" rows="4">${esc((p.achievements || []).join('\n'))}</textarea></label></div>
  <div class="row"><span class="sp"></span><button class="btn primary" type="submit">Save profile</button></div></div></form>`;
};

V.resumes = () => {
  const R = Object.values(S.resumes).sort((a, b) => b.uploadedAt.localeCompare(a.uploadedAt));
  const Vs = Object.values(S.versions).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  return `<div class="card"><div class="card-h"><h2>Upload your resume</h2><p>PDF, DOCX or TXT. The file is read in this page; the original text is stored once and never modified.</p></div>
  <label class="drop" id="drop" for="resume-file"><b>Drop your resume here or choose a file</b><span class="muted small">After reading it, you review the extracted profile before anything is saved.</span><input type="file" id="resume-file" accept=".pdf,.docx,.txt,.md,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" style="display:none"></label>
  <details><summary class="small muted" style="cursor:pointer">Or paste resume text</summary><form novalidate class="stack" data-form="paste-resume" style="margin-top:8px"><textarea name="text" id="paste-resume" rows="6" placeholder="Paste the full text of your resume"></textarea><div class="row"><button class="btn" type="submit">Read pasted text</button></div></form></details></div>
  <div class="card"><div class="card-h"><h2>Original resumes</h2><span class="pill nodot">Immutable</span></div>${R.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>File</th><th>Uploaded</th><th>Type</th><th class="r">Characters</th><th></th></tr></thead><tbody>${R.map(r => `<tr><td>${esc(r.filename)}</td><td>${fmtDT(r.uploadedAt)}</td><td>${esc(r.kind.toUpperCase())}</td><td class="r num">${r.text.length.toLocaleString('en-IN')}</td><td class="r"><button class="btn sm" type="button" data-act="view-original" data-id="${r.id}">View text</button> <button class="btn sm" type="button" data-act="reparse" data-id="${r.id}">Re-extract profile</button></td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">No resume uploaded yet.</p>'}</div>
  <div class="card"><div class="card-h"><h2>Tailored versions</h2><p>One version per generation, linked to its job. Older versions stay available for comparison.</p></div>${Vs.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Job</th><th>Version</th><th class="r">ATS coverage</th><th>Engine</th><th>Created</th><th></th></tr></thead><tbody>${Vs.map(v => { const j = S.jobs[v.jobId]; return `<tr><td>${j ? `<a href="#job-${j.id}">${esc(j.title)} · ${esc(j.company)}</a>` : '<span class="muted">Deleted job</span>'}</td><td class="num">v${v.version}</td><td class="r num">${v.coverage}%</td><td>${engineTag(v.engine)}</td><td>${fmtDT(v.createdAt)}</td><td class="r" style="white-space:nowrap"><button class="btn sm" type="button" data-act="preview-version" data-id="${v.id}">Preview</button> <button class="btn sm" type="button" data-act="compare-version" data-id="${v.id}">Compare</button> <button class="btn sm" type="button" data-act="dl-pdf" data-id="${v.id}">PDF</button> <button class="btn sm" type="button" data-act="dl-docx" data-id="${v.id}">DOCX</button></td></tr>`; }).join('')}</tbody></table></div>` : '<p class="muted">Generate a tailored resume from any job page.</p>'}</div>`;
};

V.preferences = () => {
  const p = S.ui.prefDraft || S.prefs || { titles: [], skills: [], locations: [], workModes: [], employmentTypes: ['full_time'], companyTypes: [], industries: [] };
  const amb = (p.ambiguities && p.ambiguities.length ? p.ambiguities : prefAmbiguities(p));
  const isDraft = !!S.ui.prefDraft;
  return `<div class="card"><div class="card-h"><h2>Describe the job you want</h2><p>Plain language works. The agent turns it into structured search filters you can check before anything runs.</p></div>
  <form novalidate class="stack" data-form="prefs-nl"><label class="f"><span>Your request</span><textarea name="text" id="prefs-text" rows="3" placeholder="Find entry-level Full Stack Developer and Python Developer jobs in Hyderabad, Bengaluru and remote India. I know Python, PHP, JavaScript, React, MySQL and REST APIs. I am targeting ₹4–7 LPA and prefer companies offering fresher opportunities.">${esc(p.raw || '')}</textarea></label><div class="row"><button class="btn primary" type="submit">Interpret request</button><span class="muted small">Uses ${AI.available() && S.settings.cloudPublic ? AI.name + ', with the local parser as fallback' : 'the local parser'}.</span></div></form></div>
  ${isDraft ? `<div class="banner info"><b>Check these filters.</b><span>They are not saved until you confirm.</span><span class="sp"></span><button class="btn sm" type="button" data-act="prefs-discard">Discard</button><button class="btn sm primary" type="button" data-act="prefs-confirm">Confirm and save</button></div>` : ''}
  <div class="grid g2"><form novalidate class="card" data-form="prefs-edit" id="prefs-form"><div class="card-h"><h2>Structured preferences</h2>${p.engine ? engineTag(p.engine) : ''}<span class="sp"></span><button class="btn sm primary" type="submit">${isDraft ? 'Confirm and save' : 'Save changes'}</button></div>
  <div class="fgrid">
  <label class="f wide"><span>Job titles</span><input type="text" name="titles" id="pr-titles" value="${esc((p.titles || []).join(', '))}"></label>
  <label class="f wide"><span>Skills to search with</span><input type="text" name="skills" id="pr-skills" value="${esc((p.skills || []).join(', '))}"></label>
  <label class="f wide"><span>Locations (use “Remote” for remote)</span><input type="text" name="locations" id="pr-locs" value="${esc((p.locations || []).join(', '))}"></label>
  <label class="f"><span>Experience from (yrs)</span><input type="number" step="0.5" min="0" name="expMin" id="pr-emin" value="${p.expMin ?? ''}"></label><label class="f"><span>Experience to (yrs)</span><input type="number" step="0.5" min="0" name="expMax" id="pr-emax" value="${p.expMax ?? ''}"></label>
  <label class="f"><span>Salary from (LPA)</span><input type="number" step="0.5" min="0" name="salMin" id="pr-smin" value="${p.salaryMin != null ? lpaNum(p.salaryMin) : ''}"></label><label class="f"><span>Salary to (LPA)</span><input type="number" step="0.5" min="0" name="salMax" id="pr-smax" value="${p.salaryMax != null ? lpaNum(p.salaryMax) : ''}"></label>
  <div class="f wide"><span class="muted" style="font-size:12.5px">Work modes</span><div class="row">${['remote', 'hybrid', 'onsite'].map(m => `<label class="check"><input type="checkbox" name="workModes" value="${m}" ${(p.workModes || []).includes(m) ? 'checked' : ''}>${m[0].toUpperCase() + m.slice(1)}</label>`).join('')}</div></div>
  <div class="f wide"><span class="muted" style="font-size:12.5px">Employment type</span><div class="row">${Object.entries(EMP_LABEL).map(([k, l]) => `<label class="check"><input type="checkbox" name="employmentTypes" value="${k}" ${(p.employmentTypes || []).includes(k) ? 'checked' : ''}>${l}</label>`).join('')}</div></div>
  <label class="f"><span>Company types</span><input type="text" name="companyTypes" id="pr-ctype" value="${esc((p.companyTypes || []).join(', '))}"></label><label class="f"><span>Industries</span><input type="text" name="industries" id="pr-ind" value="${esc((p.industries || []).join(', '))}"></label>
  <label class="f wide"><span>Other requirements</span><input type="text" name="other" id="pr-other" value="${esc(p.other || '')}"></label></div></form>
  <div class="stack" style="gap:16px"><div class="card"><h2>Needs confirming</h2>${amb.length ? `<ul class="list small">${amb.map(a => `<li><span class="pill warn">Check</span><span>${esc(a)}</span></li>`).join('')}</ul>` : '<p class="muted small">Nothing ambiguous.</p>'}</div>
  <div class="card"><div class="card-h"><h2>As API payload</h2><span class="sp"></span><button class="btn sm" type="button" data-act="copy-prefs">Copy</button></div><div class="pre" id="prefs-json">${esc(JSON.stringify(prefsToApiJSON(p), null, 2))}</div></div></div></div>`;
};

V.discover = () => {
  const n = S.notify || DEFAULT_NOTIFY(); const p = S.prefs || {}; const boards = boardsFor(n); const last = S.meta && S.meta.search; const run = S.ui.searching;
  const hasPrefs = (p.titles || []).length > 0; const st = (S.server && S.server.status) || null; const src = (st && st.sources) || {};
  const found = last ? (last.newIds || []).map(id => S.jobs[id]).filter(Boolean).sort((a, b) => (b.match ? b.match.score : 0) - (a.match ? a.match.score : 0)) : [];
  const links = discoveryLinks(S.prefs); const J = Object.values(S.jobs);
  const jobsFrom = { boards: J.filter(j => ATS_NAME[j.source]).length, remote: J.filter(j => REMOTE_NAME[j.source]).length };
  const remoteOn = Object.keys(REMOTE_NAME).some(k => n.feeds[k] !== false);
  const live = id => id === 'boards' ? (n.feeds.ats === false ? 'Off' : 'Connected') : id === 'remote' ? (remoteOn ? 'Connected' : 'Off') : id === 'adzuna' ? (/^ok/.test(src.adzuna || '') ? 'Connected' : 'Needs setup') : null;
  const tone = v => v === 'Connected' ? 'good' : v === 'Limited' || v === 'Needs setup' ? 'info' : v === 'Manual' ? 'warn' : '';
  const stale = st && st.lastRunAt && (Date.now() - new Date(st.lastRunAt)) > 3 * 3600e3;
  return `<section class="card">
    <div class="card-h"><h2>Search open roles</h2><span class="sp"></span><button class="btn primary" type="button" data-act="find-jobs" ${hasPrefs && !run ? '' : 'disabled'}>${icon('search')}${run ? 'Searching…' : last ? 'Search again' : 'Search now'}</button></div>
    <p class="small prose">Reads the live listings of ${boards.length} company career boards${remoteOn ? ' and the remote job feeds' : ''}, straight from this browser. A role appears only while the employer is accepting applications, and each one links to the employer’s own application page.</p>
    ${hasPrefs ? `<div class="row small"><span class="muted">Looking for</span>${p.titles.slice(0, 5).map(t => `<span class="chip acc">${esc(t)}</span>`).join('')}<span class="muted">in</span>${(p.locations || []).length ? p.locations.slice(0, 5).map(t => `<span class="chip">${esc(t)}</span>`).join('') : '<span class="chip">Anywhere in India</span>'}<a href="#preferences">Change</a></div>` : `<div class="banner"><span>Set the job titles and cities you want first, so the search knows what to keep.</span><span class="sp"></span><a class="btn sm primary" href="#preferences">Set job preferences</a></div>`}
    ${searchStatus()}
    ${!run && last && last.stats.failed && last.stats.failed.length ? `<details class="small"><summary>${last.stats.failed.length} board${last.stats.failed.length === 1 ? '' : 's'} could not be read</summary><ul class="plain">${last.stats.failed.map(f => `<li>${esc(f.name || f.token)} (${ATS_NAME[f.ats]}): ${esc(f.error)}</li>`).join('')}</ul><p class="muted">A board that keeps failing may have moved. Remove it below, or add its new careers link.</p></details>` : ''}
    ${!run && found.length ? `<h3>New from the last search</h3><div class="stack">${found.slice(0, 5).map(jobCard).join('')}</div>${found.length > 5 ? `<div class="row"><a class="btn sm" href="#jobs">See all ${found.length} new roles</a></div>` : ''}` : ''}
    ${!run && last && !found.length ? `<p class="small">Nothing new matched. Try broader titles or more cities in <a href="#preferences">Job Preferences</a>, add companies below, or import a posting you found elsewhere.</p>` : ''}
  </section>
  <section class="card"><div class="card-h"><h2>Companies searched</h2><p>${boards.length} career board${boards.length === 1 ? '' : 's'}</p><span class="sp"></span>${(n.boardsOff || []).length ? `<button class="btn sm" type="button" data-act="boards-restore">Restore ${n.boardsOff.length} removed</button>` : ''}</div>
    <p class="small muted prose">The suggested companies were checked on 10 Nov 2026: each board was live and listed open roles in India. Remove any you don’t want, and add any company that hires through Greenhouse, Lever, Ashby or SmartRecruiters.</p>
    ${boards.length ? `<div class="boards">${boards.map(b => `<span class="board"><span>${esc(b.name)}</span><span class="tiny muted">${ATS_NAME[b.ats]}</span><button type="button" class="board-x" data-act="board-remove" data-ats="${b.ats}" data-token="${esc(b.token)}" aria-label="Stop searching ${esc(b.name)}" title="Remove">${icon('x')}</button></span>`).join('')}</div>` : '<p class="muted">No companies selected. Restore the suggested list or add one below.</p>'}
    <form novalidate class="row" data-form="board-add" style="align-items:flex-end"><label class="f" style="flex:2;min-width:220px"><span>Add a company’s careers link</span><input type="text" name="board" id="bd-in" inputmode="url" autocomplete="off" placeholder="https://jobs.lever.co/company"></label><label class="f" style="min-width:160px"><span>System</span><select name="ats" id="bd-ats"><option value="">Detect from the link</option>${Object.entries(ATS_NAME).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select></label><button class="btn" type="submit">Check and add</button></form>
    <p class="tiny muted">Open the company’s careers page: if the address starts with boards.greenhouse.io, jobs.lever.co, jobs.ashbyhq.com or jobs.smartrecruiters.com, paste it here.</p>
  </section>
  <section class="card"><h2>Remote job feeds</h2><p class="small muted prose">Remote roles that are open to India or worldwide. These feeds ask not to be polled often, so each is read at most once every 6 hours.</p>
    <div class="stack"><label class="check"><input type="checkbox" data-act="feed-toggle" data-feed="remotive" ${n.feeds.remotive !== false ? 'checked' : ''}><span><b>Remotive</b> <span class="small muted">· listings link back to remotive.com</span></span></label>
    <label class="check"><input type="checkbox" data-act="feed-toggle" data-feed="remoteok" ${n.feeds.remoteok !== false ? 'checked' : ''}><span><b>Remote OK</b> <span class="small muted">· listings link back to remoteok.com</span></span></label></div>
  </section>
  <div class="grid g2">
  <form novalidate class="card" data-form="import-job"><div class="card-h"><h2>Import a job you found elsewhere</h2></div><p class="small muted">For LinkedIn, Naukri, Indeed and other sites that don’t allow automated access: paste the posting and it is scored like any other.</p>
  <label class="f"><span>Job link</span><input type="text" inputmode="url" name="url" id="ij-url" placeholder="https://"></label>
  <label class="f"><span>Job description (copy everything from the posting)</span><textarea name="text" id="ij-text" rows="8" placeholder="Title, company, location, requirements, responsibilities, salary"></textarea></label>
  <div class="row"><button class="btn primary" type="submit">Import and score</button><span class="muted small">To import several, separate postings with a line containing only ---</span></div></form>
  <div class="card"><div class="card-h"><h2>Search other platforms</h2></div><p class="small muted">${hasPrefs ? 'Ready-made searches from your preferences. Open one, then import the postings you like.' : 'Set <a href="#preferences">job preferences</a> to tailor these searches.'}</p>
  <div class="stack">${links.map(l => `<a class="btn" style="justify-content:space-between" href="${esc(l.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(l.label)}</span>${icon('ext')}</a>`).join('')}</div></div></div>
  <section class="card"><div class="card-h"><h2>Where jobs come from</h2><p>Sites that forbid automated access are never scraped or auto-submitted.</p></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Source</th><th>Status</th><th>How jobs arrive</th><th class="r">Jobs here</th></tr></thead><tbody>${PLATFORMS.map(pl => { const v = live(pl.id) || pl.status; return `<tr><td><b>${esc(pl.name)}</b></td><td><span class="pill ${tone(v)}">${v}</span></td><td class="small">${esc(pl.note)}</td><td class="r num">${pl.id in jobsFrom ? jobsFrom[pl.id] : J.filter(j => j.source === pl.id).length}</td></tr>`; }).join('')}</tbody></table></div>
  ${CLOUD ? `<p class="small"><b>Scheduled search:</b> ${st ? (stale ? `last ran ${esc(fmtDT(st.lastRunAt))}, so it is paused.` : `running; last search ${esc(relTime(st.lastDiscoveryAt || st.lastRunAt))}.`) : 'not set up yet.'} The server job repeats this search every 6 hours and alerts you about new matches. <a href="#alerts">Notifications and server setup</a></p>` : ''}</section>`;
};

V.jobs = () => {
  const f = S.ui.filter; let J = Object.values(S.jobs);
  if (f.minScore) J = J.filter(j => (j.match ? j.match.score : 0) >= f.minScore);
  const all = J.length;
  if (f.status !== 'all') J = J.filter(j => f.status === 'open' ? !['Archived', 'EmployerRejected', 'Withdrawn', 'OfferDeclined', 'RejectedByUser'].includes(j.stage) && !(isClosed(j) && stillPreparing(j)) : f.status === 'closed' ? isClosed(j) : j.stage === f.status);
  if (f.q) { const q = f.q.toLowerCase(); J = J.filter(j => (j.title + ' ' + j.company + ' ' + j.location + ' ' + (j.requiredSkills || []).join(' ')).toLowerCase().includes(q)); }
  J.sort((a, b) => f.sort === 'recent' ? (b.discoveredAt || '').localeCompare(a.discoveredAt || '') : f.sort === 'salary' ? ((b.salaryMax ?? b.salaryMin ?? -1) - (a.salaryMax ?? a.salaryMin ?? -1)) : ((b.match ? b.match.score : -1) - (a.match ? a.match.score : -1)));
  return `<form novalidate class="card" data-form="job-filter"><div class="row" style="gap:12px">
  <label class="f" style="flex:2;min-width:180px"><span>Search</span><input type="search" name="q" id="jf-q" value="${esc(f.q)}" placeholder="Title, company, skill"></label>
  <label class="f" style="min-width:150px"><span>Minimum match: <b class="num" id="jf-min-v">${f.minScore}</b></span><input type="range" name="minScore" id="jf-min" min="0" max="100" step="5" value="${f.minScore}"></label>
  <label class="f"><span>Status</span><select name="status" id="jf-status"><option value="open" ${f.status === 'open' ? 'selected' : ''}>Open to apply or in progress</option><option value="all" ${f.status === 'all' ? 'selected' : ''}>Everything</option><option value="closed" ${f.status === 'closed' ? 'selected' : ''}>Closed by the employer</option>${Object.entries(STAGES).map(([k, s]) => `<option value="${k}" ${f.status === k ? 'selected' : ''}>${s.label}</option>`).join('')}</select></label>
  <label class="f"><span>Sort</span><select name="sort" id="jf-sort"><option value="score">Best match</option><option value="recent" ${f.sort === 'recent' ? 'selected' : ''}>Newest</option><option value="salary" ${f.sort === 'salary' ? 'selected' : ''}>Highest salary</option></select></label>
  <div class="f"><span>&nbsp;</span><button class="btn" type="submit">Apply</button></div></div></form>
  <div class="row between"><span class="muted small">${J.length} job${J.length === 1 ? '' : 's'} · Excellent 85–100 · Good 70–84 · Moderate 50–69 · Poor below 50</span><div class="row"><button class="btn sm" type="button" data-act="rescore">Re-score all</button><a class="btn sm" href="#discover">Sources</a><button class="btn sm primary" type="button" data-act="find-jobs" ${S.ui.searching ? 'disabled' : ''}>${icon('search')}${S.ui.searching ? 'Searching…' : 'Search open roles'}</button></div></div>
  ${searchStatus()}
  ${J.length ? `<div class="stack">${J.map(jobCard).join('')}</div>` : all ? emptyState('No jobs match these filters', 'Lower the minimum match, clear the search box, or switch Status to “Everything”.') : emptyState('No jobs yet', 'Search the open roles on company career boards, or import a posting you found yourself.', `<button class="btn primary" type="button" data-act="find-jobs">${icon('search')}Search open roles</button><a class="btn" href="#discover">Import a job</a>`)}`;
};

V.job = id => {
  const j = S.jobs[id]; if (!j) return `<div class="card">${emptyState('Job not found', 'It may have been deleted.', '<a class="btn" href="#jobs">Back to jobs</a>')}</div>`;
  const m = j.match || {}; const tab = S.ui.tab[id] || 'match'; const v = S.versions[j.app && j.app.versionId];
  const actions = [];
  if (['Discovered', 'Analyzed'].includes(j.stage)) actions.push(`<button class="btn primary" type="button" data-act="run-workflow" data-id="${j.id}" ${isClosed(j) ? 'disabled' : ''}>${icon('bolt')}Prepare application</button>`, `<button class="btn" type="button" data-act="stage" data-id="${j.id}" data-to="Shortlisted">Shortlist</button>`);
  if (j.stage === 'Shortlisted') actions.push(`<button class="btn primary" type="button" data-act="tailor" data-id="${j.id}">Generate tailored resume</button>`);
  if (j.stage === 'ResumeGenerated') actions.push(`<button class="btn primary" type="button" data-act="prepare" data-id="${j.id}">Prepare application</button>`, `<button class="btn" type="button" data-act="tailor" data-id="${j.id}">Regenerate resume</button>`);
  if (j.stage === 'AwaitingApproval') actions.push(`<a class="btn primary" href="#approvals">Review in Approval Center</a>`);
  if (j.stage === 'Approved') actions.push(`<button class="btn primary" type="button" data-act="submit" data-id="${j.id}">Submit application</button>`);
  if (j.stage === 'SubmissionInProgress') actions.push(`<button class="btn primary" type="button" data-act="submit" data-id="${j.id}">Record submission result</button>`);
  if (EMPLOYER_STAGES.includes(j.stage) || j.stage === 'Applied') { if ((STAGES[j.stage].next || []).length) actions.push(`<button class="btn primary" type="button" data-act="status" data-id="${j.id}">Update status</button>`); }
  if (['Discovered', 'Analyzed', 'Shortlisted', 'ResumeGenerated', 'RejectedByUser'].includes(j.stage)) actions.push(`<button class="btn" type="button" data-act="stage" data-id="${j.id}" data-to="Archived">Archive</button>`);
  if (j.stage === 'Archived') actions.push(`<button class="btn" type="button" data-act="stage" data-id="${j.id}" data-to="Analyzed">Restore</button>`);
  if (j.stage === 'RejectedByUser') actions.push(`<button class="btn" type="button" data-act="stage" data-id="${j.id}" data-to="AwaitingApproval">Reconsider</button>`);
  const tabs = [['match', 'Match analysis'], ['resume', 'Tailored resume'], ['application', 'Application'], ['timeline', 'Timeline'], ['insights', 'Insights'], ['description', 'Job details']];
  let body = '';
  if (tab === 'match') body = matchTab(j);
  if (tab === 'resume') body = resumeTab(j, v);
  if (tab === 'application') body = applicationTab(j);
  if (tab === 'timeline') body = timelineTab(j);
  if (tab === 'insights') body = insightsTab(j);
  if (tab === 'description') body = descTab(j);
  return `<div class="card"><div class="row" style="gap:16px;align-items:flex-start">${scoreRing(m.score, true)}<div class="stack" style="gap:6px;flex:1;min-width:220px"><div class="row"><h2 style="font-size:21px">${esc(j.title)}</h2>${stagePill(j.stage)}${closedPill(j)}</div>${jobMeta(j)}
  <div class="row small"><span class="pill ${category(m.score || 0).tone}">${esc(m.category || 'Not scored')}</span>${j.applyUrl ? `<a href="${esc(j.applyUrl)}" target="_blank" rel="noopener noreferrer">Official posting ${icon('ext', 'style="width:12px;height:12px;vertical-align:-1px"')}</a>` : '<span class="muted">No application URL</span>'}${j.deadline ? `<span class="muted">Apply by ${fmtDate(j.deadline)}</span>` : ''}${ATS_NAME[j.source] && !j.closed ? `<span class="muted">${j.verifiedOpenAt ? `Listed as open ${esc(relTime(j.verifiedOpenAt))}` : 'Not checked yet'}</span><button class="btn sm ghost" type="button" data-act="verify-open" data-id="${j.id}">${icon('refresh')}Check now</button>` : ''}</div></div>
  <div class="row">${actions.join('')}<button class="btn ghost danger" type="button" data-act="delete-job" data-id="${j.id}">Delete</button></div></div>
  ${j.closed ? `<div class="banner bad"><span><b>This role has closed.</b> ${esc(j.company)} no longer lists it${j.closedAt ? ` (checked ${esc(fmtDT(j.closedAt))})` : ''}, so it was probably filled or withdrawn.</span><span class="sp"></span>${ATS_NAME[j.source] ? `<button class="btn sm" type="button" data-act="verify-open" data-id="${j.id}">Check again</button>` : ''}<button class="btn sm" type="button" data-act="mark-open" data-id="${j.id}">It is still open</button></div>` : j.expired ? `<div class="banner bad"><span><b>The deadline has passed.</b> Applications closed on ${esc(fmtDate(j.deadline))}.</span><span class="sp"></span><button class="btn sm" type="button" data-act="mark-open" data-id="${j.id}">It is still open</button></div>` : ''}
  ${j.suspicious ? `<div class="banner bad"><b>This listing looks suspicious.</b><span>${esc(j.suspiciousReason || 'Verify the employer before sharing personal details.')}</span></div>` : ''}
  ${j.snippet ? `<div class="banner info"><span>Found automatically on ${esc(SOURCE_NAME[j.source] || j.source)}, which only shares a short description. For an exact score, open the posting, copy the full description and paste it via <b>Job details → Edit</b>.</span></div>` : ''}</div>
  <nav class="tabs" aria-label="Job sections">${tabs.map(([k, l]) => `<a data-act="tab" data-id="${j.id}" data-tab="${k}" class="${tab === k ? 'on' : ''}">${l}</a>`).join('')}</nav>${body}`;
};
function matchTab(j) {
  const m = j.match; if (!m) return `<div class="card">${emptyState('Not scored yet', 'Score this job against your profile.', `<button class="btn primary" type="button" data-act="score" data-id="${j.id}">Score now</button>`)}</div>`;
  const W = m.weights || S.settings.weights; const wsum = sum(Object.values(W).map(Number)) || 1;
  return `<div class="grid g-side"><div class="card"><div class="card-h"><h2>Score breakdown</h2>${engineTag(m.engine)}<span class="sp"></span><span class="mono muted">S = Σ wᵢ·cᵢ / Σ wᵢ = ${m.raw}</span></div>
  <div class="stack">${Object.entries(COMP_LABEL).map(([k, l]) => { const c = m.components[k]; return `<div class="comp"><span>${l} <span class="tiny muted">${Math.round(W[k] / wsum * 100)}%</span></span><div class="bar"><i style="width:${c.v}%;${c.v < 50 ? 'background:var(--bad)' : c.v < 70 ? 'background:var(--warn)' : ''}"></i></div><b class="num" style="text-align:right">${c.v}</b><span class="tiny muted num" style="text-align:right">+${Math.round(W[k] * c.v / wsum * 10) / 10}</span></div><div class="tiny muted" style="margin:-6px 0 2px">${esc(c.note)}${c.unknown ? ' · <i>missing info, scored neutral</i>' : ''}</div>`; }).join('')}</div>
  <p class="small"><b>Recommendation:</b> ${esc(m.recommendation)}</p>${m.ai ? `<div class="stripe info small"><b>AI review</b> ${engineTag('ai')}<div class="md">${mdHTML(m.ai)}</div></div>` : AI.available() ? `<div class="row"><button class="btn sm" type="button" data-act="ai-explain" data-id="${j.id}">Ask ${AI.name} for a semantic review</button><span class="tiny muted">Optional; the score itself stays deterministic.</span></div>` : '<p class="tiny muted">Add a free Gemini key in <a href="#config">Configuration</a> for an optional AI review.</p>'}</div>
  <div class="stack" style="gap:16px"><div class="card"><h3>Required skills</h3>${chipList(m.matchedRequired, 'match')}${m.missingRequired.length ? chipList(m.missingRequired, 'miss') : ''}<h3>Preferred skills</h3>${chipList(m.matchedPreferred, 'match')}${m.missingPreferred.length ? `<div class="chips">${m.missingPreferred.map(s => `<span class="chip pref">${esc(s)}</span>`).join('')}</div><p class="tiny muted">Missing preferred skills lower the score slightly but never disqualify a job.</p>` : ''}</div>
  <div class="card"><h3>Strengths</h3>${m.strengths.length ? `<ul class="list small">${m.strengths.map(s => `<li><span class="pill good nodot">+</span><span>${esc(s)}</span></li>`).join('')}</ul>` : '<p class="muted small">None identified.</p>'}<h3>Weaknesses</h3>${m.weaknesses.length ? `<ul class="list small">${m.weaknesses.map(s => `<li><span class="pill bad nodot">−</span><span>${esc(s)}</span></li>`).join('')}</ul>` : '<p class="muted small">None identified.</p>'}${m.unknowns.length ? `<h3>Not enough information</h3><ul class="list small">${m.unknowns.map(s => `<li><span class="pill nodot">?</span><span>${esc(s)}</span></li>`).join('')}</ul>` : ''}</div>
  <div class="card"><h3>Relevant projects</h3>${m.projects.length ? hbars(m.projects.map(x => ({ label: x.name, value: x.rel, text: x.rel + '%' })), { max: 100 }) : '<p class="muted small">No projects in profile.</p>'}</div></div></div>`;
}
function resumeTab(j, v) {
  const all = Object.values(S.versions).filter(x => x.jobId === j.id).sort((a, b) => b.version - a.version);
  if (!v && !all.length) return `<div class="card">${emptyState('No tailored resume yet', 'Generate an ATS-friendly resume for this job from your verified profile.', `<button class="btn primary" type="button" data-act="tailor" data-id="${j.id}">Generate tailored resume</button>`)}</div>`;
  v = v || all[0];
  return `<div class="grid g-side"><div class="card"><div class="card-h"><h2>Version ${v.version}</h2>${engineTag(v.engine)}<span class="pill ${v.coverage >= 70 ? 'good' : v.coverage >= 50 ? 'warn' : 'bad'}">ATS coverage ${v.coverage}%</span><span class="sp"></span><button class="btn sm" type="button" data-act="compare-version" data-id="${v.id}">Compare with original</button><button class="btn sm" type="button" data-act="dl-pdf" data-id="${v.id}">${icon('dl')}PDF</button><button class="btn sm" type="button" data-act="dl-docx" data-id="${v.id}">${icon('dl')}DOCX</button></div>
  <div class="resume-doc">${resumeHTML(v.content, S.profile || {}, v.keywordsCovered)}</div><p class="tiny muted">Highlighted terms are job keywords found in this version.</p></div>
  <div class="stack" style="gap:16px"><div class="card"><h3>What changed</h3><ul class="list small">${v.content.changeLog.map(c => `<li><span class="pill acc nodot">Δ</span><span>${esc(c)}</span></li>`).join('')}</ul></div>
  <div class="card"><h3>Truthfulness guard</h3>${v.content.guard.length ? `<ul class="list small">${v.content.guard.map(g => `<li><span class="pill warn nodot">!</span><span>${esc(g)}</span></li>`).join('')}</ul>` : '<p class="small"><span class="pill good">Passed</span> Every skill, project, employer and date comes from your profile.</p>'}</div>
  <div class="card"><h3>Keywords</h3><p class="tiny muted">In the resume</p>${chipList(v.keywordsCovered, 'match')}<p class="tiny muted">Not in the resume (and not added, because your profile lacks them)</p>${chipList(v.keywordsMissing, 'miss')}</div>
  ${all.length > 1 ? `<div class="card"><h3>Other versions</h3><ul class="list small">${all.filter(x => x.id !== v.id).map(x => `<li><span class="num">v${x.version}</span><span>${fmtDT(x.createdAt)} · ${x.coverage}%</span><span class="sp"></span><button class="btn sm" type="button" data-act="use-version" data-id="${j.id}" data-v="${x.id}">Use this</button></li>`).join('')}</ul></div>` : ''}
  ${['ResumeGenerated', 'Shortlisted', 'AwaitingApproval', 'Approved'].includes(j.stage) ? `<button class="btn" type="button" data-act="tailor" data-id="${j.id}">Regenerate</button>` : ''}</div></div>`;
}
function applicationTab(j) {
  const a = j.app || {};
  if (!a.answers) return `<div class="card">${emptyState('Application not prepared', j.stage === 'ResumeGenerated' ? 'Fill the standard application questions from your verified profile.' : 'Generate a tailored resume first, then prepare the application.', j.stage === 'ResumeGenerated' ? `<button class="btn primary" type="button" data-act="prepare" data-id="${j.id}">Prepare application</button>` : (['Analyzed', 'Discovered', 'Shortlisted'].includes(j.stage) ? `<button class="btn primary" type="button" data-act="run-workflow" data-id="${j.id}">Run the workflow to approval</button>` : ''))}</div>`;
  const need = a.answers.filter(x => x.needsInput && !x.a);
  return `<div class="card"><div class="card-h"><h2>Application answers</h2>${need.length ? `<span class="pill warn">${need.length} need your input</span>` : '<span class="pill good">Complete</span>'}<span class="sp"></span>${j.stage === 'AwaitingApproval' || j.stage === 'Approved' ? '<a class="btn sm primary" href="#approvals">Edit and approve</a>' : ''}</div>
  ${a.answers.map(x => `<div class="qa"><div><b class="small">${esc(x.q)}</b>${x.required ? ' <span class="tiny muted">required</span>' : ''}</div><div class="stack" style="gap:2px"><span style="white-space:pre-wrap">${x.a ? esc(x.a) : '<span class="pill warn">Needs your input</span>'}</span><span class="tiny muted">${esc(x.evidence || (x.a ? 'Entered by you' : ''))}</span></div></div>`).join('')}
  ${a.submission ? `<div class="stripe good small"><b>Submitted</b> ${fmtDT(a.submission.at)} · reference <span class="mono">${esc(a.submission.reference)}</span>${a.submission.note ? ' · ' + esc(a.submission.note) : ''}</div>` : ''}
  ${a.approval ? `<div class="small muted">Approved ${fmtDT(a.approval.approvedAt)} · snapshot <span class="hash">${esc(a.approval.hash)}</span></div>` : ''}</div>`;
}
function timelineTab(j) {
  const a = j.app || {};
  const H = (j.history || []).slice().reverse();
  return `<div class="grid g2"><div class="card"><h2>Status history</h2><div class="timeline">${H.map(h => `<div class="tl"><b>${esc((STAGES[h.to] || { label: h.to }).label)}</b> <span class="tiny muted">${fmtDT(h.t)} · ${esc(h.by)}</span>${h.evidence ? `<div class="tiny">Evidence: ${esc(h.evidence)}</div>` : ''}${h.note ? `<div class="tiny muted">${esc(h.note)}</div>` : ''}</div>`).join('') || '<p class="muted">No history.</p>'}</div></div>
  <div class="stack" style="gap:16px"><div class="card"><div class="card-h"><h3>Recruiter</h3><span class="sp"></span><button class="btn sm" type="button" data-act="edit-recruiter" data-id="${j.id}">Edit</button></div>${a.recruiter && (a.recruiter.name || a.recruiter.email) ? `<p class="small">${esc(a.recruiter.name || '')}${a.recruiter.email ? ' · ' + esc(a.recruiter.email) : ''}${a.recruiter.phone ? ' · ' + esc(a.recruiter.phone) : ''}</p>${a.recruiter.notes ? `<p class="tiny muted">${esc(a.recruiter.notes)}</p>` : ''}` : '<p class="muted small">No recruiter details.</p>'}</div>
  <div class="card"><div class="card-h"><h3>Interviews</h3><span class="sp"></span>${reached(j, 'Applied') ? `<button class="btn sm" type="button" data-act="add-interview" data-id="${j.id}">Add interview</button>` : ''}</div>${(a.interviews || []).length ? `<ul class="list small">${a.interviews.map(iv => `<li><span class="pill ${new Date(iv.at) > Date.now() ? 'good' : ''}">${esc(iv.type || 'Interview')}</span><span>${fmtDT(iv.at)}${iv.notes ? ' · ' + esc(iv.notes) : ''}</span></li>`).join('')}</ul>` : '<p class="muted small">None scheduled.</p>'}</div>
  <div class="card"><h3>Employer feedback</h3>${a.feedback && a.feedback.text ? `<div class="stripe ${j.stage === 'EmployerRejected' ? 'bad' : 'info'} small">${esc(a.feedback.text)}<div class="tiny muted">Source: ${esc(a.feedback.source || '—')} · verified feedback, stored separately from AI analysis</div></div>` : '<p class="muted small">No feedback recorded.</p>'}</div></div></div>`;
}
function insightsTab(j) {
  const a = j.app || {}; const out = [];
  if (reached(j, 'EmployerShortlisted') || reached(j, 'InterviewScheduled')) out.push(shortlistCard(j));
  if (j.stage === 'EmployerRejected') out.push(rejectionCard(j));
  if (reached(j, 'OfferReceived')) out.push(`<div class="card"><div class="card-h"><h2>Offer</h2><span class="sp"></span><a class="btn sm" href="#offers">Compare offers</a></div>${a.offer ? offerSummary(a.offer) : '<p class="muted">Add the offer details on the Offers page.</p>'}</div>`);
  if (!out.length) out.push(`<div class="card">${emptyState('No outcome yet', 'Shortlisting and rejection analysis appear here once the employer responds. Until then, the match analysis shows likely strengths and gaps.')}</div>`);
  return out.join('');
}
function descTab(j) {
  return `<div class="grid g2"><div class="card"><div class="card-h"><h2>Extracted details</h2>${engineTag(j.extractEngine)}<span class="sp"></span><button class="btn sm" type="button" data-act="edit-job" data-id="${j.id}">Edit</button></div>
  <div class="tbl-wrap"><table class="tbl"><tbody>${[['Title', j.title], ['Company', j.company], ['Location', j.location || '—'], ['Work mode', j.workMode || 'Not stated'], ['Salary', salaryRange(j.salaryMin, j.salaryMax)], ['Experience', j.expMin != null ? `${j.expMin}${j.expMax != null ? '–' + j.expMax : '+'} years` : 'Not stated'], ['Employment', EMP_LABEL[j.employmentType] || '—'], ['Education', j.education || 'Not stated'], ['Source', SOURCE_NAME[j.source] || j.source], ['External ID', j.externalId || '—'], ['Deadline', j.deadline ? fmtDate(j.deadline) : '—'], ['Found', fmtDT(j.discoveredAt)]].map(([k, v]) => `<tr><td class="muted" style="width:130px">${k}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table></div>
  <h3>Responsibilities</h3>${(j.responsibilities || []).length ? `<ul class="small" style="margin:0;padding-left:18px">${j.responsibilities.map(r => `<li>${esc(r)}</li>`).join('')}</ul>` : '<p class="muted small">None extracted.</p>'}</div>
  <div class="card"><h2>Original description</h2><p class="tiny muted">Treated as untrusted text: it is never allowed to change the agent’s instructions.</p><div class="pre">${esc(j.description || '')}</div></div></div>`;
}
function shortlistCard(j) {
  const an = j.app && j.app.shortlistAnalysis;
  if (!an) return `<div class="card">${emptyState('Shortlisting analysis', 'Analyze why this application was likely shortlisted and get an interview plan.', `<button class="btn primary" type="button" data-act="analyze-shortlist" data-id="${j.id}">Analyze shortlisting</button>`)}</div>`;
  const r = an.report;
  return `<div class="card"><div class="card-h"><h2>Shortlisting analysis</h2>${engineTag(an.engine)}<span class="tiny muted">${fmtDT(an.at)}</span><span class="sp"></span><button class="btn sm" type="button" data-act="analyze-shortlist" data-id="${j.id}">Re-run</button></div>
  <p>${esc(r.summary || '')}</p>
  <div class="grid g2"><div class="stack">${r.requirements ? `<h3>Requirements vs your profile</h3><div class="tbl-wrap"><table class="tbl"><tbody>${r.requirements.map(x => `<tr><td>${esc(x.req)}</td><td><span class="pill ${x.status === 'met' ? 'good' : x.status === 'partial' ? 'warn' : 'bad'}">${x.status === 'met' ? 'Met' : x.status === 'partial' ? 'Partial' : 'Gap'}</span></td></tr>`).join('')}</tbody></table></div>` : ''}
  <h3>Likely contributed</h3><ul class="list small">${(r.contributors || []).map(c => `<li><span class="pill good nodot">+</span><span>${esc(c)}</span></li>`).join('')}</ul>
  <h3>Most relevant resume sections</h3><ul class="list small">${(r.sections || []).map(c => `<li><span class="pill acc nodot">§</span><span>${esc(c)}</span></li>`).join('')}</ul>
  <h3>Potential difficulties</h3><ul class="list small">${(r.weaknesses || []).map(c => `<li><span class="pill warn nodot">!</span><span>${esc(c)}</span></li>`).join('') || '<li class="muted">None identified</li>'}</ul></div>
  <div class="stack"><h3>Topics to prepare</h3><ul class="list small">${(r.prepTopics || []).map(c => `<li><span class="pill nodot">•</span><span>${esc(c)}</span></li>`).join('')}</ul>
  <h3>Likely interview questions</h3><ol class="small" style="margin:0;padding-left:20px">${(r.questions || []).map(q => `<li><span class="tiny muted">${esc(q.topic || '')}</span> ${esc(q.q || q)}</li>`).join('')}</ol></div></div>
  <h3>Preparation schedule</h3><div class="grid g3">${(r.schedule || []).map(d => `<div class="repeat"><b>Day ${d.day}: ${esc(d.focus)}</b><ul class="small" style="margin:0;padding-left:18px">${(d.tasks || []).map(t => `<li>${esc(t)}</li>`).join('')}</ul></div>`).join('')}</div></div>`;
}
function rejectionCard(j) {
  const an = j.app && j.app.rejectionAnalysis;
  if (!an) return `<div class="card">${emptyState('Rejection analysis', 'Compare the job, your resumes and any feedback to separate confirmed reasons from possibilities.', `<button class="btn primary" type="button" data-act="analyze-rejection" data-id="${j.id}">Analyze rejection</button>`)}</div>`;
  const r = an.report; const lvTone = { 'Confirmed': 'bad', 'Strongly supported': 'warn', 'Possible': 'info', 'Unknown': '' };
  return `<div class="card"><div class="card-h"><h2>Rejection analysis</h2>${engineTag(an.engine)}<span class="pill nodot">Confidence: ${esc(r.confidence || '—')}</span><span class="sp"></span><button class="btn sm" type="button" data-act="analyze-rejection" data-id="${j.id}">Re-run</button></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Evidence level</th><th>Factor</th><th>Detail</th><th>Source</th></tr></thead><tbody>${(r.reasons || []).map(x => `<tr><td><span class="pill ${lvTone[x.level] || ''}">${esc(x.level)}</span></td><td><b>${esc(x.factor)}</b></td><td class="small">${esc(x.detail)}</td><td class="small muted">${esc(x.source || '')}</td></tr>`).join('')}</tbody></table></div>
  <p class="tiny muted">Confirmed = stated by the employer · Strongly supported = documented requirement you do not meet · Possible = inferred · Unknown = not enough information. Only “Confirmed” reflects the employer’s actual reasoning.</p>
  <h3>Recommendations</h3><ul class="list small">${(r.recommendations || []).map(c => `<li><span class="pill acc nodot">→</span><span>${esc(c)}</span></li>`).join('')}</ul></div>`;
}
function offerSummary(o) {
  const total = (+o.fixed || 0) + (+o.variable || 0) + (+o.joiningBonus || 0);
  return `<div class="small">${[['Fixed', lpa(+o.fixed || null)], ['Variable', lpa(+o.variable || null)], ['Joining bonus', o.joiningBonus ? '₹' + (+o.joiningBonus).toLocaleString('en-IN') : '—'], ['First-year total', lpa(total || null)], ['Location', o.location || '—'], ['Joining date', o.joiningDate ? fmtDate(o.joiningDate) : '—'], ['Respond by', o.deadline ? fmtDate(o.deadline) : '—']].map(([k, v]) => `<div class="row between"><span class="muted">${k}</span><b class="num">${esc(v)}</b></div>`).join('')}${o.benefits ? `<p class="tiny" style="margin-top:6px">${esc(o.benefits)}</p>` : ''}</div>`;
}

V.approvals = () => {
  const J = Object.values(S.jobs).filter(j => ['AwaitingApproval', 'Approved', 'SubmissionInProgress', 'SubmissionFailed'].includes(j.stage)).sort((a, b) => (b.match ? b.match.score : 0) - (a.match ? a.match.score : 0));
  if (!J.length) return `<div class="card">${emptyState('Nothing waiting for approval', 'When the agent prepares an application it stops here. Nothing is submitted until you approve it.', '<a class="btn primary" href="#jobs">Pick a job to prepare</a>')}</div>`;
  return `<div class="banner info"><span><b>Human approval required.</b> Approving locks a snapshot of the resume and answers (SHA-256). Any later change clears the approval.</span></div>` + J.map(j => approvalCard(j)).join('');
};
function approvalCard(j) {
  const a = j.app || {}; const v = S.versions[a.versionId]; const need = (a.answers || []).filter(x => x.needsInput && !String(x.a).trim());
  const approved = j.stage === 'Approved'; const editable = j.stage === 'AwaitingApproval';
  return `<div class="card" id="ap-${j.id}"><div class="row" style="align-items:flex-start;gap:14px">${scoreRing(j.match && j.match.score)}<div class="stack" style="gap:4px;flex:1;min-width:200px"><div class="row"><h2><a href="#job-${j.id}" style="color:inherit;text-decoration:none">${esc(j.title)}</a></h2>${stagePill(j.stage)}${a.savedForLater ? '<span class="pill nodot">Saved for later</span>' : ''}</div>${jobMeta(j)}</div>
  <div class="row">${editable ? `<button class="btn primary" type="button" data-act="approve" data-id="${j.id}" ${need.length ? 'disabled title="Answer every required question first"' : ''}>Approve and lock</button><button class="btn" type="button" data-act="later" data-id="${j.id}">Save for later</button><button class="btn danger" type="button" data-act="reject-app" data-id="${j.id}">Reject</button>` : ''}
  ${approved ? `<button class="btn primary" type="button" data-act="submit" data-id="${j.id}">Submit application</button><button class="btn" type="button" data-act="unapprove" data-id="${j.id}">Revoke approval</button>` : ''}${j.stage === 'SubmissionInProgress' ? `<button class="btn primary" type="button" data-act="submit" data-id="${j.id}">Record submission result</button>` : ''}${j.stage === 'SubmissionFailed' ? `<button class="btn primary" type="button" data-act="stage" data-id="${j.id}" data-to="AwaitingApproval">Re-open for approval</button>` : ''}</div></div>
  ${approved && a.approval ? `<div class="stripe good small">Approved ${fmtDT(a.approval.approvedAt)} · expires ${fmtDT(a.approval.expiresAt)}<br><span class="hash">snapshot ${esc(a.approval.hash)}</span></div>` : ''}
  <div class="grid g2"><div class="stack"><div class="row"><h3>Resume</h3>${v ? `<span class="pill ${v.coverage >= 70 ? 'good' : 'warn'}">v${v.version} · ATS ${v.coverage}%</span>${engineTag(v.engine)}<span class="sp"></span><button class="btn sm" type="button" data-act="preview-version" data-id="${v.id}">Preview</button>${editable || approved ? `<button class="btn sm" type="button" data-act="tailor" data-id="${j.id}">Regenerate</button>` : ''}` : '<span class="pill bad">Missing</span>'}</div>
  ${v ? `<div class="pre" style="max-height:260px">${esc(resumeText(v.content, S.profile || {}))}</div>${v.content.guard.length ? `<p class="tiny"><span class="pill warn">Guard</span> ${v.content.guard.length} unsupported item(s) were removed.</p>` : '<p class="tiny"><span class="pill good">Guard passed</span> No unverified claims.</p>'}` : ''}
  <h3>Employer</h3><p class="small">${esc(j.company)} · ${j.applyUrl ? `<a href="${esc(j.applyUrl)}" target="_blank" rel="noopener noreferrer">${esc(hostOf(j.applyUrl))}</a>` : 'No URL'} · ${esc(SOURCE_NAME[j.source] || j.source)}</p></div>
  <form novalidate class="stack" data-form="answers" data-id="${j.id}"><div class="row"><h3>Answers</h3>${need.length ? `<span class="pill warn">${need.length} need input</span>` : '<span class="pill good">All answered</span>'}</div>
  ${(a.answers || []).map(x => `<label class="f"><span>${esc(x.q)}${x.required ? ' *' : ''} <span class="tiny" style="color:${x.draft ? 'var(--warn)' : 'var(--muted)'}">${esc(x.evidence || (x.a ? 'Entered by you' : 'Not in your profile'))}</span></span>${x.key === 'cover' || x.key === 'whyUs' || x.key === 'custom' ? `<textarea name="${x.id}" id="ans-${x.id}" rows="${x.key === 'cover' ? 5 : 2}" ${editable ? '' : 'readonly'}>${esc(x.a)}</textarea>` : `<input type="text" name="${x.id}" id="ans-${x.id}" value="${esc(x.a)}" ${editable ? '' : 'readonly'} ${x.needsInput && !x.a ? 'style="border-color:var(--warn)"' : ''}>`}</label>`).join('')}
  ${editable ? `<label class="f"><span>Extra employer questions (one per line, answered only from your profile)</span><textarea name="__custom" id="ans-custom-${j.id}" rows="2" placeholder="Do you have experience with Celery?"></textarea></label><div class="row"><button class="btn" type="submit">Save answers</button><button class="btn" type="button" data-act="add-custom" data-id="${j.id}">Answer extra questions</button></div>` : '<p class="tiny muted">Answers are locked while approved. Revoke approval to edit.</p>'}</form></div></div>`;
}

V.tracker = () => {
  const J = Object.values(S.jobs);
  const mode = S.ui.trackerMode || 'board';
  const cols = [['Preparing', ['Shortlisted', 'ResumeGenerated']], ['Awaiting approval', ['AwaitingApproval', 'Approved', 'SubmissionInProgress', 'SubmissionFailed']], ['Applied', ['Applied']], ['Under review', ['UnderReview']], ['Shortlisted by employer', ['EmployerShortlisted']], ['Interview', ['InterviewScheduled']], ['Offer', ['OfferReceived', 'OfferAccepted']], ['Closed', ['EmployerRejected', 'Withdrawn', 'OfferDeclined', 'RejectedByUser']]];
  const tracked = J.filter(j => !['Discovered', 'Analyzed', 'Archived'].includes(j.stage));
  const head = `<div class="row between"><div class="row"><button class="btn sm ${mode === 'board' ? 'primary' : ''}" type="button" data-act="tracker-mode" data-mode="board">Board</button><button class="btn sm ${mode === 'table' ? 'primary' : ''}" type="button" data-act="tracker-mode" data-mode="table">Table</button></div><span class="muted small">${tracked.length} tracked · status changes follow a controlled state machine and need evidence</span></div>`;
  if (!tracked.length) return head + `<div class="card">${emptyState('No applications yet', 'Shortlist a job and the agent tracks it from here.', '<a class="btn primary" href="#jobs">Recommended jobs</a>')}</div>`;
  if (mode === 'table') return head + `<div class="card"><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Company</th><th>Role</th><th>Status</th><th class="r">Match</th><th>Resume</th><th>Applied</th><th>Last update</th><th>Recruiter</th><th></th></tr></thead><tbody>${tracked.sort((a, b) => (b.updatedAt || '').localeCompare(a.updatedAt || '')).map(j => { const v = S.versions[j.app && j.app.versionId]; const ap = (j.history || []).find(h => h.to === 'Applied'); return `<tr class="click" data-act="open-job" data-id="${j.id}"><td><b>${esc(j.company)}</b></td><td>${esc(j.title)}</td><td>${stagePill(j.stage)}</td><td class="r num">${j.match ? j.match.score : '—'}</td><td>${v ? 'v' + v.version + ' · ' + v.coverage + '%' : '—'}</td><td>${ap ? fmtDate(ap.t) : '—'}</td><td>${fmtDate(j.updatedAt)}</td><td class="small">${esc((j.app && j.app.recruiter && j.app.recruiter.name) || '—')}</td><td>${(STAGES[j.stage].next || []).length && reached(j, 'Applied') ? `<button class="btn sm" type="button" data-act="status" data-id="${j.id}">Update</button>` : ''}</td></tr>`; }).join('')}</tbody></table></div></div>`;
  return head + `<div class="kanban">${cols.map(([t, sts]) => { const items = tracked.filter(j => sts.includes(j.stage)); return `<div class="col"><h4><span>${t}</span><span class="num">${items.length}</span></h4>${items.map(j => `<div class="kcard" data-act="open-job" data-id="${j.id}" tabindex="0"><b class="small">${esc(j.company)}</b><span class="small">${esc(j.title)}</span><div class="row">${stagePill(j.stage)}<span class="tiny muted num">${j.match ? j.match.score : ''}</span></div>${reached(j, 'Applied') && (STAGES[j.stage].next || []).length ? `<button class="btn sm" type="button" data-act="status" data-id="${j.id}">Update status</button>` : ''}</div>`).join('')}</div>`; }).join('')}</div>`;
};

V.shortlisting = () => {
  const J = Object.values(S.jobs).filter(j => reached(j, 'EmployerShortlisted') || reached(j, 'InterviewScheduled'));
  if (!J.length) return `<div class="card">${emptyState('No employer shortlists yet', 'When an employer shortlists you, record it in the tracker and the analysis appears here.', '<a class="btn" href="#tracker">Application Tracker</a>')}</div>`;
  const A = analytics();
  return `<div class="card"><h2>What is working</h2><div class="grid g3"><div><b class="num" style="font:700 26px var(--f-display)">${A.shortlistRate}%</b><p class="muted small">of applications shortlisted</p></div><div><b class="num" style="font:700 26px var(--f-display)">${A.coverageShort ?? '—'}%</b><p class="muted small">average ATS coverage on shortlisted resumes</p></div><div><b style="font:650 16px var(--f-display)">${esc(A.companies.join(', ') || '—')}</b><p class="muted small">companies interested in you</p></div></div></div>` + J.map(j => `<div class="stack"><div class="row"><h3><a href="#job-${j.id}">${esc(j.title)} · ${esc(j.company)}</a></h3>${stagePill(j.stage)}</div>${shortlistCard(j)}</div>`).join('');
};
V.rejections = () => {
  const J = Object.values(S.jobs).filter(j => j.stage === 'EmployerRejected');
  if (!J.length) return `<div class="card">${emptyState('No rejections recorded', 'Rejections are only recorded from a recruiter response or another reliable source, never guessed.')}</div>`;
  const A = analytics(); const all = J.map(j => j.app && j.app.rejectionAnalysis).filter(Boolean).flatMap(a => a.report.reasons || []);
  const byLevel = l => all.filter(r => r.level === l).length; const factors = new Map(); all.filter(r => r.level !== 'Unknown').forEach(r => { const f = r.factor.replace(/:.*$/, ''); factors.set(f, (factors.get(f) || 0) + 1); });
  return `<div class="grid g2"><div class="card"><h2>Patterns across ${J.length} rejection${J.length > 1 ? 's' : ''}</h2>${factors.size ? hbars([...factors.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map(([l, v]) => ({ label: l, value: v }))) : '<p class="muted small">Run the analysis on each rejection to see patterns.</p>'}
  <div class="row small"><span class="pill bad">Confirmed ${byLevel('Confirmed')}</span><span class="pill warn">Strongly supported ${byLevel('Strongly supported')}</span><span class="pill info">Possible ${byLevel('Possible')}</span></div></div>
  <div class="card"><h2>Skills missing in rejected jobs</h2>${A.rejMissing.length ? hbars(A.rejMissing.map(([l, v]) => ({ label: l, value: v, color: 'var(--bad)' }))) : '<p class="muted small">No skill gaps recorded on rejected jobs.</p>'}<p class="tiny muted">Rejection rate ${A.rejectionRate}% · average ATS coverage on rejected resumes ${A.coverageRej ?? '—'}% vs ${A.coverageShort ?? '—'}% on shortlisted.</p></div></div>` + J.map(j => `<div class="stack"><div class="row"><h3><a href="#job-${j.id}">${esc(j.title)} · ${esc(j.company)}</a></h3>${stagePill(j.stage)}<span class="sp"></span><button class="btn sm" type="button" data-act="edit-feedback" data-id="${j.id}">Employer feedback</button></div>${rejectionCard(j)}</div>`).join('');
};
V.interviews = () => {
  const items = Object.values(S.jobs).flatMap(j => ((j.app && j.app.interviews) || []).map(iv => ({ j, iv }))).sort((a, b) => a.iv.at.localeCompare(b.iv.at));
  const up = items.filter(x => new Date(x.iv.at) > Date.now() - 3 * 3600e3), past = items.filter(x => !up.includes(x));
  const candidates = Object.values(S.jobs).filter(j => ['EmployerShortlisted', 'InterviewScheduled'].includes(j.stage));
  const card = ({ j, iv }) => { const prep = iv.prep; return `<div class="card"><div class="card-h"><h2>${esc(j.company)} · ${esc(j.title)}</h2><span class="pill good">${esc(iv.type || 'Interview')}</span><span class="sp"></span><span class="num"><b>${fmtDT(iv.at)}</b></span></div>${iv.notes ? `<p class="small muted">${esc(iv.notes)}</p>` : ''}
  ${prep ? `<div class="row">${engineTag(prep.engine)}<span class="tiny muted">Plan created ${fmtDT(prep.at)}</span><span class="sp"></span><button class="btn sm" type="button" data-act="interview-prep" data-id="${j.id}" data-iv="${iv.id}">Rebuild plan</button></div>
  <div class="grid g3">${prep.schedule.map(d => `<div class="repeat"><b>Day ${d.day}: ${esc(d.focus)}</b><ul class="small" style="margin:0;padding-left:18px">${(d.tasks || []).map(t => `<li>${esc(t)}</li>`).join('')}</ul></div>`).join('')}</div>
  <h3>Practice questions</h3><ol class="small" style="margin:0;padding-left:20px">${prep.questions.map(q => `<li><span class="tiny muted">${esc(q.topic || '')}</span> ${esc(q.q || q)}</li>`).join('')}</ol>` : `<div class="row"><button class="btn primary" type="button" data-act="interview-prep" data-id="${j.id}" data-iv="${iv.id}">Build preparation plan</button><span class="muted small">Day-by-day plan from the job’s requirements and your gaps.</span></div>`}</div>`; };
  return `<div class="row between"><span class="muted small">${up.length} upcoming · ${past.length} past</span>${candidates.length ? `<div class="row"><label for="iv-job" class="small muted">Add interview for</label><select id="iv-job">${candidates.map(j => `<option value="${j.id}">${esc(j.company)} · ${esc(j.title)}</option>`).join('')}</select><button class="btn sm primary" type="button" data-act="add-interview-sel">Add</button></div>` : ''}</div>
  ${up.length ? up.map(card).join('') : `<div class="card">${emptyState('No upcoming interviews', 'Record an interview from the tracker when an employer schedules one.')}</div>`}${past.length ? `<h3>Past interviews</h3>${past.map(card).join('')}` : ''}`;
};
V.offers = () => {
  const J = Object.values(S.jobs).filter(j => reached(j, 'OfferReceived'));
  if (!J.length) return `<div class="card">${emptyState('No offers yet', 'When you receive an offer, record it in the tracker. Then compare salary, benefits and fit here.')}</div>`;
  const rows = J.map(j => { const o = (j.app && j.app.offer) || {}; const total = (+o.fixed || 0) + (+o.variable || 0) + (+o.joiningBonus || 0); return { j, o, total }; });
  const best = k => Math.max(...rows.map(r => k(r) || 0));
  const an = S.meta.offerAnalysis;
  return `<div class="card"><div class="card-h"><h2>Offer comparison</h2><span class="sp"></span><button class="btn sm primary" type="button" data-act="analyze-offers">Analyze offers</button></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th></th>${rows.map(r => `<th><a href="#job-${r.j.id}">${esc(r.j.company)}</a><div class="tiny muted" style="text-transform:none;letter-spacing:0">${esc(r.j.title)}</div></th>`).join('')}</tr></thead><tbody>
  ${[['Status', r => stagePill(r.j.stage)], ['Fixed salary', r => `<b class="num" ${+r.o.fixed && +r.o.fixed === best(x => +x.o.fixed) ? 'style="color:var(--good)"' : ''}>${lpa(+r.o.fixed || null)}</b>`], ['Variable', r => lpa(+r.o.variable || null)], ['Joining bonus', r => r.o.joiningBonus ? '₹' + (+r.o.joiningBonus).toLocaleString('en-IN') : '—'], ['First-year total', r => `<b class="num" ${r.total && r.total === best(x => x.total) ? 'style="color:var(--good)"' : ''}>${lpa(r.total || null)}</b>`], ['Monthly fixed (gross)', r => r.o.fixed ? '₹' + Math.round(+r.o.fixed / 12).toLocaleString('en-IN') : '—'], ['Location', r => esc(r.o.location || r.j.location || '—')], ['Work mode', r => esc(r.j.workMode || '—')], ['Joining date', r => r.o.joiningDate ? fmtDate(r.o.joiningDate) : '—'], ['Respond by', r => r.o.deadline ? fmtDate(r.o.deadline) : '—'], ['Benefits', r => `<span class="small">${esc(r.o.benefits || '—')}</span>`], ['Match score', r => r.j.match ? r.j.match.score : '—'], ['', r => `<div class="stack" style="gap:4px"><button class="btn sm" type="button" data-act="edit-offer" data-id="${r.j.id}">Edit offer</button>${r.j.stage === 'OfferReceived' ? `<button class="btn sm primary" type="button" data-act="offer-decide" data-id="${r.j.id}" data-to="OfferAccepted">Accept</button><button class="btn sm" type="button" data-act="offer-decide" data-id="${r.j.id}" data-to="OfferDeclined">Decline</button>` : ''}</div>`]].map(([l, f]) => `<tr><td class="muted">${l}</td>${rows.map(r => `<td>${f(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="tiny muted">Gross figures as entered. In-hand pay depends on tax regime, PF and deductions.</p></div>
  ${an ? `<div class="card"><div class="card-h"><h2>Offer analysis</h2>${engineTag(an.engine)}<span class="tiny muted">${fmtDT(an.at)}</span></div><div class="md">${mdHTML(an.md)}</div></div>` : ''}`;
};
V.analytics = () => {
  const A = analytics();
  const tiles = [['Shortlisting rate', A.shortlistRate + '%', `${A.shortlisted} of ${A.applied} applications`], ['Rejection rate', A.rejectionRate + '%', `${A.rejected} rejected`], ['Interview rate', A.interviewRate + '%', `${A.interviews} interviewed`], ['Offer conversion', A.offerRate + '%', `${A.offers} offers from interviews`]];
  const locs = Object.entries(A.locs).sort((a, b) => b[1].jobs - a[1].jobs).slice(0, 8);
  const months = Object.keys(A.salMonth).sort().slice(-6);
  return `<div class="grid g4">${tiles.map(([l, v, s]) => `<div class="card"><span class="muted small">${l}</span><b style="font:700 30px var(--f-display)" class="num">${v}</b><span class="tiny muted">${s}</span></div>`).join('')}</div>
  <div class="grid g2"><div class="card"><h2>Funnel</h2>${hbars([['Discovered', A.total], ['Matched 70+', A.matching], ['Applied', A.applied], ['Shortlisted', A.shortlisted], ['Interviewed', A.interviews], ['Offers', A.offers]].map(([l, v]) => ({ label: l, value: v })))}</div>
  <div class="card"><h2>Match score distribution</h2>${vbars(['<30', '30–49', '50–69', '70–84', '85+'].map((l, i) => ({ label: l, value: A.hist[i], color: ['var(--bad)', 'var(--bad)', 'var(--warn)', 'var(--accent)', 'var(--good)'][i] })))}</div>
  <div class="card"><h2>Most common missing skills</h2>${A.missing.length ? hbars(A.missing.map(([l, v]) => ({ label: l, value: v, text: v + ' job' + (v > 1 ? 's' : '') }))) : '<p class="muted small">No gaps recorded yet.</p>'}</div>
  <div class="card"><h2>Location opportunities</h2>${locs.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Location</th><th class="r">Jobs</th><th class="r">Avg match</th><th class="r">Median pay</th></tr></thead><tbody>${locs.map(([c, v]) => `<tr><td>${esc(c)}</td><td class="r num">${v.jobs}</td><td class="r num">${v.scores.length ? Math.round(sum(v.scores) / v.scores.length) : '—'}</td><td class="r num">${v.sal.length ? lpa(v.sal.sort((a, b) => a - b)[Math.floor(v.sal.length / 2)]) : '—'}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted small">No data.</p>'}</div>
  <div class="card"><h2>Job categories</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Category</th><th class="r">Jobs</th><th class="r">Avg match</th><th class="r">Applied</th><th class="r">Shortlisted</th></tr></thead><tbody>${Object.entries(A.cats).sort((a, b) => b[1].jobs - a[1].jobs).map(([c, v]) => `<tr><td>${esc(c)}</td><td class="r num">${v.jobs}</td><td class="r num">${v.avgScore ?? '—'}</td><td class="r num">${v.applied}</td><td class="r num">${v.shortlisted}${v.applied ? ` <span class="tiny muted">(${pct(v.shortlisted, v.applied)}%)</span>` : ''}</td></tr>`).join('') || '<tr><td colspan="5" class="muted">No data</td></tr>'}</tbody></table></div></div>
  <div class="card"><h2>Sources</h2><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Source</th><th class="r">Jobs</th><th class="r">Applied</th><th class="r">Shortlisted</th></tr></thead><tbody>${Object.entries(A.sources).map(([s, v]) => `<tr><td>${esc(s)}</td><td class="r num">${v.jobs}</td><td class="r num">${v.applied}</td><td class="r num">${v.shortlisted}</td></tr>`).join('') || '<tr><td colspan="4" class="muted">No data</td></tr>'}</tbody></table></div></div>
  <div class="card"><h2>Salary trend (median of stated ranges)</h2>${vbars(months.map(m => { const v = A.salMonth[m].sort((a, b) => a - b); return { label: new Date(m + '-01').toLocaleDateString('en-IN', { month: 'short' }), value: lpaNum(v[Math.floor(v.length / 2)]) }; }), { fmt: v => v + 'L' })}</div>
  <div class="card"><h2>Resume performance</h2><div class="grid g2"><div><b class="num" style="font:700 26px var(--f-display)">${A.coverageShort ?? '—'}%</b><p class="muted small">average ATS coverage, shortlisted</p></div><div><b class="num" style="font:700 26px var(--f-display)">${A.coverageRej ?? '—'}%</b><p class="muted small">average ATS coverage, rejected</p></div></div><p class="tiny muted">A large gap suggests keyword coverage matters for your target roles; a small gap points to other factors.</p></div></div>
  <div class="card"><div class="card-h"><h2>Career reports</h2><span class="sp"></span><button class="btn sm" type="button" data-act="report" data-type="weekly">Generate weekly report</button><button class="btn sm" type="button" data-act="report" data-type="monthly">Generate monthly report</button></div>
  ${S.reports.length ? S.reports.slice(0, 6).map((r, i) => `<details ${i === 0 ? 'open' : ''} class="repeat"><summary style="cursor:pointer"><b>${r.type === 'weekly' ? 'Weekly' : 'Monthly'} report</b> <span class="tiny muted">${fmtDT(r.createdAt)}</span></summary><div class="md">${mdHTML(r.md)}</div><div class="row"><button class="btn sm" type="button" data-act="report-dl" data-id="${r.id}" data-fmt="md">Download .md</button><button class="btn sm" type="button" data-act="report-dl" data-id="${r.id}" data-fmt="docx">Download .docx</button><button class="btn sm" type="button" data-act="report-copy" data-id="${r.id}">Copy</button></div></details>`).join('') : '<p class="muted small">No reports yet.</p>'}</div>`;
};
V.activity = () => `<div class="card"><div class="card-h"><h2>Agent activity</h2><p>Every important action is recorded with the agent and engine that produced it.</p><span class="sp"></span><span class="muted small">${S.logs.length} entries (latest 300 kept)</span></div>
  ${S.logs.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Time</th><th>Agent</th><th>Action</th><th>Details</th><th>Engine</th></tr></thead><tbody>${S.logs.slice(0, 200).map(l => `<tr><td class="num small" style="white-space:nowrap">${fmtDT(l.t)}</td><td class="small"><b>${esc(l.agent)}</b></td><td class="small">${esc(l.action)}</td><td class="small muted">${esc(l.detail)}</td><td>${engineTag(l.engine)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">No activity yet.</p>'}</div>`;
V.config = () => {
  const s = S.settings; const W = s.weights; const tot = sum(Object.values(W).map(Number));
  return `<div class="grid g2"><form novalidate class="card" data-form="settings-ai"><div class="card-h"><h2>AI provider</h2><span class="sp"></span><button class="btn sm primary" type="submit">Save</button></div>
  <p class="small">Every feature works with the built-in local engine. Optionally add a free Google Gemini key for AI-written tailoring, analyses and chat. Get one at <a href="https://aistudio.google.com/apikey" target="_blank" rel="noopener noreferrer">aistudio.google.com/apikey</a>.</p>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Provider</th><th>Status</th><th>Used for</th></tr></thead><tbody>
  <tr><td><b>Local engine</b></td><td><span class="pill good">Always on</span></td><td class="small">Scoring formula, parsing rules, templates, fallback for everything</td></tr>
  <tr><td><b>Gemini (free tier)</b></td><td>${s.aiKey ? (CAP.sampleOK === false ? '<span class="pill bad">Key rejected</span>' : '<span class="pill good">Key saved</span>') : '<span class="pill">Not set</span>'}</td><td class="small">Parsing, tailoring, analyses, chat</td></tr></tbody></table></div>
  <div class="fgrid"><label class="f"><span>Gemini API key</span><input type="password" name="aiKey" id="cfg-aikey" value="${esc(s.aiKey || '')}" autocomplete="off" placeholder="AIza…"></label><label class="f"><span>Model</span><input type="text" name="aiModel" id="cfg-aimodel" value="${esc(s.aiModel || 'gemini-2.5-flash')}"></label></div>
  <label class="check"><input type="checkbox" name="cloudPublic" id="cfg-public" ${s.cloudPublic ? 'checked' : ''}>Use Gemini (job descriptions, search requests and, if allowed below, your profile)</label>
  <label class="f"><span>Personal data (resume, profile, answers)</span><select name="cloudPersonal" id="cfg-personal"><option value="ask" ${s.cloudPersonal === 'ask' ? 'selected' : ''}>Ask me the first time</option><option value="allow" ${s.cloudPersonal === 'allow' ? 'selected' : ''}>Allow Gemini</option><option value="deny" ${s.cloudPersonal === 'deny' ? 'selected' : ''}>Local engine only</option></select></label>
  <p class="tiny muted">On Google’s free tier, prompts may be used to improve Google’s products. The key is stored in your private settings row and sent only to Google.</p>
  <div class="fgrid"><label class="f"><span>Approval expires after (days)</span><input type="number" min="1" max="60" name="approvalDays" id="cfg-days" value="${s.approvalDays}"></label><label class="f"><span>Auto-shortlist when the agent runs batches (min score)</span><input type="number" min="0" max="100" name="autoShortlist" id="cfg-auto" value="${s.autoShortlist}"></label></div></form>
  <form novalidate class="card" data-form="settings-weights"><div class="card-h"><h2>Scoring weights</h2><span class="pill ${tot === 100 ? 'good' : 'warn'}" id="w-total">Total ${tot}%</span><span class="sp"></span><button class="btn sm" type="button" data-act="weights-reset">Reset</button><button class="btn sm primary" type="submit">Save and re-score</button></div>
  <p class="small muted">S = 0.30K + 0.20E + 0.10Q + 0.15P + 0.10R + 0.10L + 0.05C by default. Weights are normalised if they do not add up to 100.</p>
  <div class="stack">${Object.entries(COMP_LABEL).map(([k, l]) => `<label class="comp wrow"><span>${l} <span class="mono muted">${k}</span></span><input type="range" min="0" max="50" step="1" name="${k}" id="w-${k}" value="${W[k]}" data-act-input="weight"><b class="num" id="wv-${k}" style="text-align:right">${W[k]}%</b></label>`).join('')}</div></form></div>
  <div class="card"><div class="card-h"><h2>Job platform integrations</h2><span class="sp"></span><a class="btn sm" href="#discover">Open discovery</a></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Platform</th><th>Status</th><th>Notes</th></tr></thead><tbody>${PLATFORMS.map(p => `<tr><td>${esc(p.name)}</td><td><span class="pill ${p.status === 'Connected' ? 'good' : p.status === 'Limited' ? 'info' : 'warn'}">${p.status}</span></td><td class="small">${esc(p.note)}</td></tr>`).join('')}</tbody></table></div></div>
  ${S.mode === 'cloud' ? `<div class="card"><div class="card-h"><h2>Account</h2><span class="sp"></span><button class="btn sm" type="button" data-act="signout">Sign out</button></div><p class="small">Signed in as <b>${esc(S.session.user.email)}</b>. You stay signed in on this device until you sign out, or until it goes ${IDLE_DAYS} days without being used. Your data lives in your Supabase project, protected by row-level security so only this account can read it.</p><form novalidate class="row" data-form="change-password"><label class="f" style="flex:1;min-width:200px"><span>New password</span><input type="password" name="pw" id="cfg-pw" autocomplete="new-password" minlength="8"></label><button class="btn" type="submit" style="align-self:flex-end">Change password</button></form></div>` : ''}
  <div class="card"><div class="card-h"><h2>Appearance</h2><p>Currently showing the ${esc(Theme.effective())} theme.</p></div><div class="theme-opts">${[['light', 'Light', 'Bright surfaces for daytime work.', ['#F1F4F3', '#FFFFFF', '#0B6B63']], ['dark', 'Dark', 'Low-glare surfaces for night sessions.', ['#0D1413', '#141D1B', '#3BBFAE']], ['auto', 'Auto', 'Follows your device setting.', null]].map(([k, l, d, c]) => `<button type="button" class="theme-opt" data-act="theme" data-theme="${k}" aria-pressed="${Theme.get() === k}"><span class="theme-swatch" aria-hidden="true">${c ? `<i style="background:${c[0]}"></i><i style="background:${c[1]};border-left:6px solid ${c[2]}"></i>` : `<i style="background:linear-gradient(135deg,#F1F4F3 50%,#0D1413 50%)"></i><i style="background:linear-gradient(135deg,#FFFFFF 50%,#141D1B 50%)"></i>`}</span><b>${l}</b><span class="small muted">${d}</span></button>`).join('')}</div></div>
  <div class="grid g2"><div class="card"><h2>Your data</h2><p class="small">${S.mode === 'cloud' ? 'Stored in your Supabase cloud database, readable only by your account.' : S.mode === 'local' ? 'Stored in this browser only.' : 'Not stored.'} ${Object.keys(S.jobs).length} jobs, ${Object.keys(S.versions).length} resume versions, ${Object.keys(S.resumes).length} original resume(s).</p>
  <div class="row"><button class="btn" type="button" data-act="export">Export all data (JSON)</button><button class="btn danger" type="button" data-act="delete-all">Delete all my data</button></div></div>
  <div class="card"><h2>Safeguards in force</h2><ul class="list small">${['Applications are never submitted without your explicit approval of an immutable snapshot.', 'Tailored resumes are checked: skills, employers, dates and years not in your profile are removed.', 'Job descriptions are treated as untrusted text and cannot change the agent’s instructions.', 'CAPTCHAs, logins and platform restrictions are never bypassed; LinkedIn is not scraped.', 'An application is marked Applied only after you record a confirmation or reference number.', 'Rejections are recorded only from a recruiter response or another reliable source.', 'AI explanations are stored separately from verified employer feedback.'].map(t => `<li><span class="tick">${icon('check')}</span><span>${t}</span></li>`).join('')}</ul></div></div>`;
};
